BEGIN;

-- gcp-pca-b
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-b-q1": {"point": "ステートフル・DaemonSet・GPU・きめ細かいネットワーク制御など、コンテナ基盤に「自分で細部まで制御したい」という要件が並ぶならGKE。シンプルさ優先ならCloud Run系。", "why_asked": "PCA試験ではコンピュートサービス選定が頻出。「コンテナを使う」という共通点だけでGKEを選んでしまう誤答が典型的で、要件文の細部（DaemonSet、GPU、細かなネットワーク制御）まで読み取れるかが問われる。", "eg": "部活の道具を、備え付けの体育館（Cloud Run）で借りるか、自分たちで倉庫を組んで棚から配線まで自由に管理する部室（GKE）にするかという違いに近い。細かい管理が要るなら部室を選ぶ。"}, "gcp-pca-b-q2": {"point": "インメモリDB（SAP HANA等）のように大容量メモリそのものが性能を左右する用途なら、メモリ最適化（Mシリーズ）。", "why_asked": "マシンファミリー選定はコスト最適化の基本だが、CPUコア数だけを見て汎用や、CPU重視のコンピュート最適化を選んでしまう誤答が起きやすい。要件文の「メモリ容量」というキーワードに反応できるかが問われる。", "eg": "引っ越しトラックを選ぶとき、荷物の重さ（CPU負荷）ではなく荷物の体積（メモリ容量）がボトルネックなら、パワーより荷台の大きいトラックを選ぶのと同じ考え方。"}, "gcp-pca-b-q3": {"point": "複数VMから同時に読み書きするPOSIX互換の共有ファイルシステムが要件ならFilestore。", "why_asked": "「共有ストレージ」と聞いてPersistent DiskやCloud Storageを連想する誤解が起きやすい。PDは基本1台のVMにアタッチする前提、Cloud Storageはオブジェクトストレージであってファイルシステムではない、という制約の違いを理解しているかが問われる。", "eg": "会社の共有フォルダのように、複数人（VM）が同時に同じ書類棚を開いて読み書きできる仕組みに相当する。各自のUSBメモリ（ローカルディスク）を持ち寄っても共有にはならない。"}, "gcp-pca-b-q4": {"point": "トランザクションDBのように高IOPS・低レイテンシが要件ならSSD系（SSD Persistent DiskまたはHyperdisk）。", "why_asked": "「安いから」という理由だけでHDD PDやNearlineを選ぶと性能要件を満たせず本番障害につながる。要件文の「トランザクション」「高IOPS」「低レイテンシ」という言葉から、コストより性能を優先すべき場面だと読み取れるかが試される。", "eg": "銀行の窓口業務のように1件1件をすぐさばく必要がある処理には、反応の速い担当者（SSD）を置く。書類を後でまとめて処理する倉庫番（HDDや低頻度アクセス向けストレージ）では間に合わない。"}, "gcp-pca-b-q5": {"point": "経過日数などの条件でオブジェクトのクラス変更や削除を自動化したいならライフサイクル管理ルールを使う。", "why_asked": "手作業やスクリプトの自作でも実現できてしまうため、マネージド機能を使うべき理由（運用負荷とヒューマンエラーのリスクを下げる）まで理解しているかが問われる。", "eg": "図書館が「返却から1年たった本は自動的に書庫へ、5年たったら除籍」という規則を最初から仕組み化しておけば、司書が毎回棚を見て回らなくて済むのと同じ発想。"}, "gcp-pca-b-q6": {"point": "Googleアカウントを持たない相手に、期限付き・対象限定でアクセスを渡したいなら署名付きURL。", "why_asked": "「外部と共有」と聞くと権限付与やバケット公開を連想しがちだが、それは過剰な露出になる。必要な相手に必要なものだけ必要な時間だけ渡す、という最小権限の判断がPCAでは繰り返し問われる。", "eg": "映画館の当日券のような仕組みに近い。会員証（Googleアカウント）を持たない人でも、その1回・その時間だけ入場できる券（署名付きURL）を渡せば十分で、合鍵（アカウント権限）を渡す必要はない。"}, "gcp-pca-b-q7": {"point": "学習からデプロイ・推論までを一気通貫のマネージド基盤でやりたいならVertex AI。", "why_asked": "MLインフラを自前のCompute Engineで組み立てる案は「技術的には可能」に見えるため紛らわしい。「作れるか」ではなく「運用負荷やスピードの観点でマネージドサービスを使うべきか」を問う設計判断が繰り返し出る。", "eg": "料理でいえば、材料の仕入れから調理・盛り付けまで揃った厨房（Vertex AI）を使うか、鍋やコンロを一から自分で用意する（Compute Engine手組み）かの違いに近い。"}, "gcp-pca-b-q8": {"point": "決まった時刻に処理を起動したいだけならCloud Scheduler。VMを常時起動してcrontabを管理する必要はない。", "why_asked": "「昔ながらのcron」の発想でVM常時起動を選んでしまうと、使っていない時間も課金され続け、保守対象（OSパッチ等）も増える。運用負荷とコストの両面からマネージドサービスへの置き換えを判断できるかが問われる。", "eg": "家の目覚まし時計をわざわざ人を雇って毎朝起こしてもらう（VM常時起動）のではなく、時計そのもの（Cloud Scheduler）に任せるようなもの。"}, "gcp-pca-b-q9": {"point": "バージョン管理とトラフィック分割を、インフラ管理なしで使いたいならApp Engine。", "why_asked": "同じことをCompute Engine＋Nginxでも実現できるため「できるかできないか」で判断すると誤る。同じ結果を得るのに運用負荷が最小な選択肢はどれか、という視点が繰り返し問われる。", "eg": "劇場の演目を新旧入れ替えるとき、照明や舞台設備をすべて自前で組む（自前Nginx群）のではなく、初めから舞台と設備が整った劇場（App Engine）を借りるイメージ。"}, "gcp-pca-b-q10": {"point": "形式を問わず生データを安価・高耐久に大量集約する土台が要件ならCloud Storage。", "why_asked": "データレイクという言葉から構造化DB（Cloud SQL等）を連想してしまう誤答が起きやすいが、データレイクの本質は形式を問わずそのまま貯めることであり、スキーマを事前に決めるRDBとは思想が逆になる。", "eg": "何でも受け入れる倉庫（Cloud Storage）と、決まった棚にしか物を置けない整理された書庫（Cloud SQL）の違いに近い。データレイクは前者の発想。"}, "gcp-pca-b-q11": {"point": "同一エンティティのメッセージを発行順に処理したいならordering keyを使う。", "why_asked": "Pub/Subは基本的に順序を保証しないメッセージングサービスであり、「トピックを1つにすれば順序が保証される」という誤解が起きやすい。順序保証はキー単位で明示的に有効化する機能であることの理解が問われる。", "eg": "銀行の窓口が客ごとに整理券を分けて、同じ客の複数の用件だけは来た順に処理する仕組みに近い。窓口（トピック）を1つにしても他の客との順番までは揃わない。"}, "gcp-pca-b-q12": {"point": "分析ではなく、大量キーに対するミリ秒級のオンライン参照が要件ならBigtable。分析用途ならBigQuery。", "why_asked": "「ビッグデータ＝BigQuery」という短絡的な連想で誤答しやすい。BigQueryは大規模分析に強い一方でクエリのレイテンシは秒単位になりうるため、単件の低レイテンシ参照には向かない。用途で使い分ける判断が問われる。", "eg": "コンビニのレジで即座に商品価格を1件引く作業と、月末に全店舗の売上を集計する作業は、同じ「データを見る」でも求められる速さの種類が違う、という違いに相当する。"}, "gcp-pca-b-q13": {"point": "組織やフォルダ配下の全プロジェクトに一貫したFW方針を強制したいなら階層型ファイアウォールポリシー。", "why_asked": "各プロジェクトのVPCファイアウォールルールを個別に設定する運用は、規模が大きくなるほど設定漏れや不整合を生みやすい。個々に設定するのではなく上位階層で一元的に強制する、という統治の発想が問われる。", "eg": "本社が定めた就業規則を各支店の掲示板にコピーして回るのではなく、本社規則がそのまま全支店に自動的に効く仕組みを作るようなもの。"}, "gcp-pca-b-q14": {"point": "Google APIや公開済みの内部サービスへ、インターネットに出さず内部IPだけでプライベートに到達したいならPrivate Service Connect。", "why_asked": "「プライベートに繋ぐ」というとVPCピアリングやCloud NATを連想しがちだが、ピアリングはVPC同士の直接接続でGoogle管理サービスには使えず、Cloud NATはあくまで外向き通信用の仕組みである。目的に合った機能を選べるかが問われる。", "eg": "会社の中庭を通らずに、建物内の専用通路（内部エンドポイント）だけで別部署の窓口まで行けるようにする仕組みに近い。"}, "gcp-pca-b-q15": {"point": "IPアドレスを固定し続けたいなら、最初から静的IPを予約して割り当てる。", "why_asked": "エフェメラルIPは再作成のたびに変わる仕様であるため、DNSやクライアントの設定が固定IPを前提にしていると障害につながる。「変わるものをその都度追いかける」のではなく「最初から変わらないものを用意する」設計判断が問われる。", "eg": "店の電話番号を毎回変えて、変わるたびにお客さんに電話し直すのではなく、最初から固定電話番号を契約しておくようなもの。"}, "gcp-pca-b-q16": {"point": "VPC内部だけで有効な名前解決が要件ならCloud DNSのプライベートゾーン。", "why_asked": "社内向けの名前解決のためにhostsファイルを手で編集したり、公開DNSに内部IPを登録したりする運用は、保守性が悪いだけでなく内部構成の情報漏えいにもつながる。「社内限定」という要件を正しいスコープの機能で満たせるかが問われる。", "eg": "社内でしか通じない内線番号表（プライベートゾーン）を用意するようなもの。これを社外向けの電話帳（公開DNS）に載せると社内の情報が外に漏れてしまう。"}, "gcp-pca-b-q17": {"point": "複数のVPCやオンプレ拠点を、推移的に繋がるハブ&スポークで一元管理したいならNetwork Connectivity Center。", "why_asked": "VPCピアリングは非推移的（AとBがピアでもBとCがピアなら自動でAとCが繋がるわけではない）という制約があり、多拠点でピアリングを総当たりしようとすると接続数が拠点数の二乗で増えていく。この制約を理解し集約管理できる仕組みを選べるかが問われる。", "eg": "支店同士を1本ずつ電話線で結ぶ（総当たり配線）のではなく、全支店を本社の交換機（ハブ）に繋いで本社経由でどの支店とも話せるようにする仕組みに近い。"}, "gcp-pca-b-q18": {"point": "VPC内部のクライアントからしかアクセスしないバックエンド層の負荷分散なら内部ロードバランサ。", "why_asked": "「ロードバランサ＝外部に公開するもの」という思い込みから外部LBを選んでしまう誤答が起きやすい。内部限定の通信をわざわざ外部LB経由にすると、不要にインターネット向けの経路や露出面が生まれてしまう。", "eg": "建物内の各部署をつなぐ内線案内係（内部LB）と、外部からの来客を案内する受付（外部LB）は役割が違う。社内だけで完結する用件をわざわざ受付に回さない。"}, "gcp-pca-b-q19": {"point": "単一リージョン内でゾーン障害にも耐えるブロックストレージが要件ならリージョン永続ディスク（2ゾーン同期複製）。", "why_asked": "単一ゾーンの標準永続ディスクは、そのゾーンが丸ごと落ちるとデータにアクセスできなくなる。「永続ディスクだから永続的に安全」という誤解を正し、ゾーン障害に耐えるには複製先が必要という理解を問う。", "eg": "大事な台帳を1冊だけ金庫に入れておく（単一ゾーンPD）のではなく、2つの離れた部屋にリアルタイムで複写しておく（リージョンPD）ようなもの。片方の部屋が使えなくなっても台帳は残る。"}, "gcp-pca-b-q20": {"point": "CPU使用率以外のアプリ固有の指標（キュー長等）でスケールさせたいなら、Cloud Monitoringのカスタム指標に基づくオートスケーラポリシーを設定する。", "why_asked": "MIGのオートスケールはデフォルトでCPU使用率を見ると思われがちで、「CPU以外は使えない」という誤解が起きやすい。実際にはCloud Monitoringに送られる任意の指標をスケーリング条件にできるため、要件に応じた指標選定の理解が問われる。", "eg": "行列の長さ（キュー長）を見てレジを増やすか、レジ担当者の忙しさ（CPU）だけを見て増やすかの違いに近い。行列が伸びているのに担当者がまだ余裕そうに見える場面では、キュー長を見た方が実態を捉えられる。"}, "gcp-pca-b-q21": {"point": "本番・非本番の分離とポリシーの一元適用が要件なら、環境ごとにフォルダを分けてフォルダ単位でポリシーとIAMを適用する。", "why_asked": "命名規則やプロジェクトの並び順だけで環境を区別する運用は強制力がなく設定ミスや事故を防げない。IAMや組織ポリシーを継承させられるリソース階層（フォルダ）の役割を理解しているかが問われる。", "eg": "本番棟と開発棟を同じフロアに置いて名札だけで区別する（命名規則頼み）のではなく、フロアそのものを分けて（フォルダ分離）入館ルールをフロアごとに変えるようなもの。"}, "gcp-pca-b-q22": {"point": "長期のサービスアカウント鍵を発行せずに一時的に権限を借りたいなら、サービスアカウントのなりすまし（インパーソネーション）で短命の認証情報を得る。", "why_asked": "SAのJSON鍵はファイルとして持ち出せてしまうため、漏えいすると鍵が無効化されるまで悪用され続けるリスクがある。インパーソネーションは短命トークンしか発行しないため漏えい時の被害が限定的、という設計思想の理解が問われる。", "eg": "一度使ったら失効する期限付きの入館証（インパーソネーション）を借りるのと、合鍵を作って渡してしまう（長期鍵の発行）のとでは、無くしたときのリスクがまったく違う。"}, "gcp-pca-b-q23": {"point": "特定のリージョン内にしかリソースを作らせたくない（データ主権要件）なら、組織ポリシーのリソースロケーション制約を使う。", "why_asked": "手順書に書く、事後に見つけて消すといった人手の運用は強制力がなく違反を未然に防げない。データ主権はコンプライアンス上の要件であり、システムレベルで機械的に強制する組織ポリシーの役割を理解しているかが問われる。", "eg": "「この国の倉庫にしか荷物を置かない」という社則を社員の自覚に任せるのではなく、そもそも他の倉庫には荷物を入れられないように入口を制限してしまうイメージ。"}, "gcp-pca-b-q24": {"point": "大量データからPIIを自動検出・分類・マスキングしたいならSensitive Data Protection（旧Cloud DLP）。", "why_asked": "「暗号化しておけば個人情報保護は十分」という誤解が起きやすいが、暗号化はデータの秘匿手段であって、そもそもどこにPIIがあるかを見つけたりマスキングしたりする機能ではない。目的に合ったサービスを選べるかが問われる。", "eg": "大量の書類の中から個人情報が書かれた箇所だけを自動で見つけて黒塗りする専門スタッフに近い。書類全体を金庫にしまう（暗号化）だけでは、中身のどこに個人情報があるかは分からないまま。"}, "gcp-pca-b-q25": {"point": "メモリ上で処理中のデータまで暗号化したい（使用中データの保護）ならConfidential VM。", "why_asked": "「暗号化」と聞くと保存時暗号化（ディスク）や通信時のTLSを思い浮かべがちだが、これらはデータのライフサイクルのうち保存・通信しか守らない。CPU内で処理している最中のメモリ上データまで守るには別の技術が要る、という区別が問われる。", "eg": "金庫（保存時暗号化）と封筒（通信時のTLS）はあっても、机の上で書類を広げて作業している間（処理中）は無防備、という状態を防ぐ仕組みに近い。"}, "gcp-pca-b-q26": {"point": "署名（アテステーション）のあるイメージだけをGKEにデプロイさせたいならBinary Authorizationのポリシーを使う。", "why_asked": "イメージ名の命名規則や事後チェックだけに頼る運用は、悪意あるイメージや検証不足のイメージが本番に混入するのを未然に防げない。デプロイの入口で機械的に検証・拒否する統制の仕組みを理解しているかが問われる。", "eg": "空港の保安検査のように、搭乗（デプロイ）の前に必ず検品済みの証明（署名）を確認し、無いものは通さない仕組みに近い。"}, "gcp-pca-b-q27": {"point": "長期間の運用で溜まった過剰権限をデータに基づいて特定・削減したいならIAM Recommenderの推奨を使う。", "why_asked": "感覚で権限を削る運用は、本当に使われている権限まで誤って削って業務を止めてしまうリスクがある。実際の利用状況に基づいて過剰権限を検出する仕組みの存在と役割を理解しているかが問われる。", "eg": "何年も使われていない部屋の合鍵を、入退室記録（利用データ）を見て機械的に洗い出し、回収を提案してくれる管理人のようなもの。"}, "gcp-pca-b-q28": {"point": "なりすまされにくいFWの対象指定をしたいなら、ネットワークタグよりサービスアカウント基準を使う。", "why_asked": "ネットワークタグは誰でもVMに付け替えられるため、悪意あるユーザーが正規のタグを自分のVMに付けてFWルールをすり抜けられる可能性がある。サービスアカウントはIAM権限がないと変更できないため、より安全な指定方法であるという違いが問われる。", "eg": "入館対象を「誰でも巻ける腕章（タグ）」で判定するか、「発行に審査が要る社員証（サービスアカウント）」で判定するかの違いに近い。後者の方がなりすましにくい。"}, "gcp-pca-b-q29": {"point": "機密データの保護は「中身の暗号化（CMEK）」と「持ち出し防止（VPC Service Controls）」の二段構えで考える。", "why_asked": "権限管理を簡単にするために全員へOwnerを付与したり、共有を楽にするためにバケットを公開したりする案は、運用の手間を減らす代わりにセキュリティを大きく犠牲にする典型的な誤答パターン。「便利さ」と「保護」を混同していないかが問われる。", "eg": "貴重品を金庫に入れて鍵をかける（CMEK）だけでなく、建物の外周にも警備員を置いて持ち出しを見張る（VPC Service Controls）、という二重の備えに近い。"}, "gcp-pca-b-q30": {"point": "契約なしで月内の稼働時間が長いほど自動的に効く割引なら継続利用割引（SUD）。契約が要るのは確約利用割引（CUD）。", "why_asked": "「割引を受けるには契約が必要」という思い込みから、既に何もしなくても適用されているSUDの存在を見落としやすい。両者の適用条件（自動か契約か）の違いを正しく区別できるかが問われる。", "eg": "長く使うほど自動で割引される月額サブスク（SUD）と、あらかじめ1年分をまとめて予約するとさらに安くなる年間契約（CUD）の違いに近い。"}, "gcp-pca-b-q31": {"point": "予算超過を早期に検知したいなら、Cloud Billingの予算としきい値アラートを設定する。", "why_asked": "月末の請求書で気づく運用は、その時点で既に予算を超過しており対応が後手に回る。あらかじめしきい値（例: 50%/90%到達）で通知する仕組みを能動的に設定できるかが問われる。", "eg": "おこづかい帳を月末に見返して使いすぎに気づく（後手）のではなく、半分使った時点でスマホに通知が来る（予算アラート）ようにしておくイメージ。"}, "gcp-pca-b-q32": {"point": "部門別・サービス別に詳細なコストを継続的に分析したいなら、請求データをBigQueryにエクスポートしてSQL/BIで分析する。", "why_asked": "コンソールの月次サマリは全体の大まかな傾向しか見えず、部門やサービス単位への内訳の深掘りには向かない。詳細な分析には生データをBigQueryに出してクエリで自由に集計する、という発想の転換が問われる。", "eg": "月次のレシート合計だけを見る（コンソールのサマリ）のではなく、レシートの明細を1件ずつデータベースに入れて、部門別・商品別に自由に集計できるようにするイメージ。"}, "gcp-pca-b-q33": {"point": "大規模ローンチでクォータ超過が見込まれるなら、事前にクォータ増加をリクエストしておく。", "why_asked": "クォータは申請すれば引き上げられるものだが、その処理には一定の時間がかかる。「当日になってから申請すればいい」と考えて後回しにすると、審査が間に合わずローンチ自体が失敗するリスクがある、という時間軸の理解が問われる。", "eg": "大きなイベントの来場者数が事前に読めているなら、当日に慌てて会場を広げるのではなく、前もって会場の増枠を申請しておくようなもの。"}, "gcp-pca-b-q34": {"point": "可観測性を保ちつつログコストを下げたいなら、不要なログ（正常時のヘルスチェック等）だけを除外フィルタで取り込み対象から外す。", "why_asked": "ログコストを下げるために「全ログ収集を止める」という極端な対応をすると、必要な障害調査用のログまで失ってしまう。全部取るか全部止めるかの二択ではなく、条件を絞って必要なものだけ残す、という粒度の細かい判断が問われる。", "eg": "郵便受けに届く広告チラシ（不要なヘルスチェックログ）だけを事前に断って、大事な手紙（重要なログ）はそのまま受け取るようにする仕組みに近い。"}, "gcp-pca-b-q35": {"point": "本番投入前に想定ピーク負荷で要件を満たせるか確かめたいなら負荷テストを実施する。", "why_asked": "「本番投入後にユーザーの反応で確認する」という進め方は、性能問題が実際のユーザーに影響してから発覚するという最悪の順序になる。信頼性の確保は事後対応ではなく事前検証で作り込む、という設計思想が問われる。", "eg": "橋を実際に車を通す前に、想定される最大の重さで耐荷重試験をしておくようなもの。開通後に崩れてからでは遅い。"}, "gcp-pca-b-q36": {"point": "問題を能動的に早期検知したいなら、ダッシュボードと（SLOバーンレート等の）アラートポリシーで監視する。", "why_asked": "「ユーザーからの報告で初めて障害に気づく」運用は受動的で、既に多くのユーザーに影響が出た後になってしまう。Well-Architectedの運用性の観点では、問題が広がる前に自ら検知する能動的な監視体制が求められる。", "eg": "体調不良に気づく手段として、倒れてから病院に運ばれる（報告待ち）のではなく、日頃からバイタルを常時計測してアラームが鳴る仕組み（ダッシュボード＋アラート）を持っておくイメージ。"}, "gcp-pca-b-q37": {"point": "証明書更新やスケール調整などの反復作業に追われているなら、スクリプトやIaC、パイプラインで自動化する。", "why_asked": "人を増やして手作業を維持する対応は、根本原因（作業自体が反復的でミスを生みやすい）を解決しないまま、コストと属人化のリスクだけを増やしてしまう。運用性向上の本筋は自動化によるトイル（繰り返し作業）の削減である、という理解が問われる。", "eg": "毎回手作業で行っていた更新を、決まった手順として仕組み化してしまえば、人は判断が必要な仕事に時間を使えるようになる、というイメージ。"}, "gcp-pca-b-q38": {"point": "動的APIの頻繁参照データはMemorystoreでキャッシュ、静的コンテンツはCloud CDNで配信して、バックエンド負荷とレイテンシを同時に下げる。", "why_asked": "「毎回正確な最新データをDBから取る」ことにこだわると、同じ問い合わせが繰り返されるたびにバックエンドへ負荷がかかり、レイテンシも下がらない。頻繁に参照されるが更新頻度は低いデータをキャッシュ層で吸収する、という定番パターンの理解が問われる。", "eg": "よく聞かれる質問への答えを受付にあらかじめ貼り出しておけば、毎回奥の窓口（バックエンドDB）まで行かなくても即答できる、というイメージ。"}, "gcp-pca-b-q39": {"point": "新旧2系統を並行稼働させ、切替後に問題があれば即座に旧環境へ戻したいならブルー/グリーンデプロイ。", "why_asked": "本番に直接上書きするデプロイは、問題発生時に戻す対象そのものが残っていないため復旧が困難になる。切替とロールバックを素早く行うには、旧環境をすぐに消さず並行して残しておく設計が必要、という理解が問われる。", "eg": "新店舗を裏でこっそり完成させておき、開店日に看板だけを切り替える。もし新店舗の評判が悪ければ、まだ残っている旧店舗にすぐ看板を戻せる、というイメージ。"}, "gcp-pca-b-q40": {"point": "インフラ変更をレビュー・差分確認・再現可能な形で管理したいなら、TerraformなどのIaCで宣言的に管理し、変更はコードレビューとplanで確認する。", "why_asked": "コンソールでの直接変更は誰が何をいつ変えたかの記録が残らず、同じ環境を再現することも難しい。実装管理の観点では、変更を人の記憶や口頭合意に頼らず、コードと差分確認という機械的なプロセスに落とし込めるかが問われる。", "eg": "家をリフォームするとき、口頭の打ち合わせだけで工事を始める（直接変更）のではなく、設計図（コード）を直し、着工前に変更箇所（plan）をみんなで確認してから進めるイメージ。"}, "gcp-pca-b-q41": {"point": "新バージョンを少数のトラフィックから段階的に広げたいなら、トラフィック分割（カナリア）で割合を徐々に新バージョンへ移す。", "why_asked": "新バージョンを一度に100%へ切り替える運用は、不具合があった場合に全ユーザーへ同時に影響が及ぶ。少数のユーザーで先に様子を見てから拡大する、というリスクを段階的に取る発想が実装管理で繰り返し問われる。", "eg": "新メニューをまず来店客の1割だけに提供して反応を見てから、問題なければ徐々に全員に広げていく試食のようなイメージ。一気に全員に出して不評だったときの被害が大きい。"}, "gcp-pca-b-q42": {"point": "多数のGKEクラスタに一貫した構成・ポリシーをGitを起点に継続的に適用・是正したいなら、Config Sync（GitOps）を使う。", "why_asked": "クラスタごとに手作業でkubectl applyする運用は、クラスタが増えるほど設定漏れや構成のズレ（ドリフト）が生じやすい。GitOpsはGitの内容こそが正しい状態として自動的に是正し続けるため、多数クラスタの統制に向く、という理解が問われる。", "eg": "全店舗のマニュアルを本部の1冊（Gitリポジトリ）にまとめておき、各店の実際の運用が本部マニュアルとズレていたら自動的に元に戻す仕組みに近い。"}, "gcp-pca-b-q43": {"point": "リリース直後の重大な不具合に備えるなら、バージョン管理されたイミュータブルな成果物を用意し、直前バージョンへ即ロールバックできるようにしておく。", "why_asked": "本番環境に直接パッチを当てる運用は、その場しのぎで直せても元の状態が残っていないため、より深刻な問題が起きたときに戻せなくなる。事前に戻し先を用意しておくという備えの発想が実装管理で問われる。", "eg": "新聞の刷り直し（新バージョン）に誤りがあっても、前号（直前バージョン）をそのまま保管してあれば、すぐに前号を配り直せる、というイメージ。"}, "gcp-pca-b-q44": {"point": "グローバルに低レイテンシかつ単一リージョン障害でも継続するアクティブ/アクティブ構成にするなら、複数リージョンへのバックエンド配置と、グローバルロードバランサでの最寄り/健全なリージョンへのルーティングをセットで考える。", "why_asked": "単一リージョンに集約する構成は、その1箇所が落ちると全体が止まる単一障害点になる。高可用性を「バックエンドを増やす」だけで満たそうとせず、「増やしたバックエンドへどう振り分けるか」まで含めて考えられるかが問われる。", "eg": "店を複数の都市に出しておく（マルチリージョン）だけでなく、案内係（グローバルLB）が客を一番近くて営業中の店へ誘導する仕組みも合わせて用意する、というイメージ。片方だけでは機能しない。"}, "gcp-pca-b-q45": {"point": "Cloud SQLでゾーン障害時に自動フェイルオーバーさせたいなら高可用性（HA）構成にし、別ゾーンの同期スタンバイへ切り替える。", "why_asked": "単一ゾーンの単一インスタンス運用は、そのゾーンが落ちるとDBごと止まってしまう。バックアップだけでは復旧に時間がかかり目標復旧時間（RTO）を満たせないケースが多いため、自動フェイルオーバーの仕組みそのものを選べるかが問われる。", "eg": "主力選手が倒れたときにすぐ交代できるよう、控えの選手（同期スタンバイ）を別のフロア（別ゾーン）に待機させておくイメージ。"}, "gcp-pca-b-q46": {"point": "RTO（復旧までに許容できる時間）を極小化したいミッションクリティカルな要件なら、常時稼働のホットスタンバイを選ぶ。", "why_asked": "DR戦略にはバックアップ&リストア→コールド→ウォーム→ホットスタンバイの順にRTOが短くなりコストが上がる段階があり、要件文の「RTOを極小化」というキーワードから最もコストの高いホットスタンバイを選ぶ判断ができるかが問われる。コストを抑えたいだけの要件では過剰な選択になる点も併せて理解する必要がある。", "eg": "火事に例えると、被災してから消防隊を結成する（バックアップ&リストア）のと、常駐の消防隊（ホットスタンバイ）がすぐ駆けつけるのとでは対応の速さがまったく違う。その分、常駐の消防隊を維持するコストは高い。"}, "gcp-pca-b-q47": {"point": "依存サービスの一時的なエラーやスロットリングには、リトライ間隔を徐々に広げる指数バックオフ（必要ならジッタを加える）で対処する。", "why_asked": "失敗直後に即座に何度も連打リトライすると、既に負荷がかかっている相手サービスをさらに過負荷にし、障害を悪化させてしまう。「早く再試行すること」ではなく「相手の回復を待ちながら賢く再試行すること」が正しい、という理解が問われる。", "eg": "混雑した電話にひたすらリダイヤルし続けるとかえってつながりにくくなる。少しずつ間隔を空けて掛け直す方が、結果的につながりやすい、というイメージ。"}, "gcp-pca-b-q48": {"point": "1リージョン全停止時にトラフィックを健全なリージョンへ自動的に向けたいなら、グローバルロードバランサ＋ヘルスチェックで不健全なリージョンを自動的に除外する。", "why_asked": "DNSを手で書き換える方法は、変更が全世界に伝播するまでに時間がかかり（TTLの影響）、障害発生から復旧までのタイムラグが大きくなる。ヘルスチェックによって自動的かつ即座に切り替わる仕組みとの違いが問われる。", "eg": "受付（グローバルLB）が各支店の営業状況（ヘルスチェック）を常に把握していて、閉まっている支店には最初から客を案内しない、という仕組みに近い。"}, "gcp-pca-b-q49": {"point": "非必須の依存サービスが落ちても主要機能は維持したいなら、グレースフルデグラデーション（縮退運転）で設計する。", "why_asked": "依存サービスが1つでも落ちたらアプリ全体を止めてしまう設計は影響範囲を過剰に広げてしまう。全か無かではなく、非必須な部分だけを諦めて主要機能は守る、という段階的な考え方が問われる。", "eg": "エスカレーターが止まっても階段で上の階に行ける建物のように、一部の設備が使えなくても主要な機能（移動そのもの）は保たれる、というイメージ。建物全体を閉鎖する必要はない。"}, "gcp-pca-b-q50": {"point": "DR計画が実際に機能するか確実にしたいなら、定期的なDR訓練（フェイルオーバー演習）とバックアップからの復元テストを行う。", "why_asked": "バックアップを取っているだけで復元できるかどうかを確認していないと、いざという時に実は復元できない、という事態が起こりうる。DRは計画を立てること自体ではなく計画が実際に機能することを検証し続けること、という理解が問われる。", "eg": "避難訓練を一度もせずに避難経路図だけを掲示しておくと、実際の災害時にうまく動けないことがある。定期的に訓練しておくことで、いざという時に計画通り動けるかどうかを確かめられる、というイメージ。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-b')
  AND q.explanation_data IS NOT NULL;

-- gcp-pca-c
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-c-q1": {"point": "「トラフィックがない時間帯は課金をゼロにしたい」かつ「コンテナのまま動かしたい」ならCloud Run。App Engine Flexibleは常時起動が前提なのでここでは選べない。", "why_asked": "「サーバーレス」と一口に言っても、App Engine Flexible/GKE/GCEはノードやインスタンスが常時存在し完全にはゼロにならない点が実務での盲点になりやすい。要件文の「コストをゼロにしたい」「運用負荷を最小化」を見て、本当にゼロスケールするサービスを見極めさせる出題。", "eg": "使った時間だけ払う時間貸し駐車場と、使わない日があっても料金がかかる月極め駐車場の違い。Cloud Runは前者、GCEやFlexibleは後者に近い。"}, "gcp-pca-c-q2": {"point": "「中断されても再実行できる」かつ「コスト最優先」ならSpot VM。本番の止まれない処理には使わない。", "why_asked": "「コストを最小化したい」という要件文だけを見てSpot VMに飛びつく前に、対象のワークロードが中断を許容できるかどうかを確認できるかを試す出題。本番常時稼働の設問との対比で問われることが多い。", "eg": "飛行機のキャンセル待ち直前販売のチケット。定価より大幅に安いが、満席になれば急に乗れなくなる。予定が崩れても困らない人だけが使う。"}, "gcp-pca-c-q3": {"point": "「標準ランタイムで済む」かつ「瞬時スケール＋ゼロスケールが要る」ならApp Engine Standard。カスタムのシステムライブラリが必要ならFlexibleへ切り替える。", "why_asked": "App Engine StandardとFlexibleの使い分けはPCA頻出。Flexibleは通常のVMベースで起動が遅くゼロスケールできない点との対比を、要件文の「ミリ秒級」「任意のライブラリは不要」から見抜けるかを問う。", "eg": "常設の屋台と、毎回一から組み立てる特設ブースの違い。屋台(Standard)はシャッターを開ければ一瞬で営業できるが、特設ブース(Flexible)は組み立てに時間がかかり、使わない日でも骨組みを残しておく必要がある。"}, "gcp-pca-c-q4": {"point": "「他テナントと物理ホストを共有できない」というライセンス/コンプライアンス要件が出たらSole-tenantノード。", "why_asked": "Shielded VMとの混同が典型。Shielded VMはブート改ざん防止などのセキュリティ機能であり、物理ホストを専有するかどうかとは別軸の話である点を識別させる出題。", "eg": "ホテルの共用大浴場と貸切風呂の違い。他の宿泊客と設備(物理ホスト)を共有してはいけない契約なら、貸切(専有)を選ぶしかない。"}, "gcp-pca-c-q5": {"point": "「負荷に応じた台数増減」と「壊れた台の自動置換」の両方が要件なら、水平オートスケーラとヘルスチェックによる自動修復を両方設定する。", "why_asked": "MIGの機能は「台数を調整する」スケーリングと「健全性を保つ」自動修復という別々の軸に分かれる点が盲点。片方だけでは要件を満たさないことを確認させる出題。", "eg": "工場の生産ライン。注文量に応じてライン数そのものを増減させる仕組みと、故障した機械を自動検知してすぐ予備機に切り替える仕組みは、別々に用意しておく必要がある。"}, "gcp-pca-c-q6": {"point": "「ノード管理を完全に手放したい」かつ「Pod単位の課金でよい」ならAutopilot。ノード構成を細かく制御したいならStandardを選ぶ。", "why_asked": "AutopilotとStandardの選択は運用負荷とコントロールのトレードオフとして頻出。「運用を減らしたい」「ノード構成の細かな制御は不要」という要件文のキーワードに反応できるかを問う。", "eg": "全部お任せの定食屋と、自分で食材を仕入れて仕込むビュッフェの違い。Autopilotは食べた分だけ払う定食屋、Standardは仕入れ(ノード)も自分で管理するビュッフェ。"}, "gcp-pca-c-q7": {"point": "GCEの通常VMはホストメンテナンス時、既定でライブマイグレーションにより無停止で継続する（Spotや一部専用ハードウェア構成は例外）。", "why_asked": "「メンテナンス＝停止する」という誤解を正す出題。可用性設計でSpot VMやGPUを使う一部構成など、ライブマイグレーション非対応の例外を区別できるかも問われる。", "eg": "オーケストラの演奏中に、疲れた奏者をこっそり交代させても、観客(利用者)は演奏が途切れたことに気づかない。"}, "gcp-pca-c-q8": {"point": "「ネットワークは一元管理、各チームは割り当て区画にリソースを作るだけ」という要件なら共有VPC。", "why_asked": "VPCピアリングとの混同が典型。ピアリングは接続はできるが各VPCの管理主体は分かれたまま、という「接続」と「管理の集中」の違いを識別させる出題。", "eg": "学校の体育館を複数のクラブが交代で使うが、施設の維持や鍵の管理は用務員さんが一括で行う。各クラブは割り当てられた時間・区画を使うだけでよい。"}, "gcp-pca-c-q9": {"point": "「世界中から単一IPで最寄りへ振り分けたい」というグローバル・単一入口の要件なら、グローバル外部アプリケーションロードバランサ。", "why_asked": "DNSラウンドロビンとの違いを問う。DNSラウンドロビンは単一IPではなく複数IPを順番に返す方式で、健全性判定やレイテンシに基づく最適な振り分けができない点が弱点として狙われる。", "eg": "郵便番号ひとつでどの地域から出しても、自動的に一番近い配達センターへ仕分けられる仕組み。"}, "gcp-pca-c-q10": {"point": "「専用の高帯域・低レイテンシ・SLA付きの物理接続」で「数十TB規模」ならDedicated Interconnect。", "why_asked": "Cloud VPNとの使い分けが頻出論点。VPNはインターネット経由のため帯域・レイテンシ・SLAの保証が弱く、大容量・低遅延要件では不足する点を問う。", "eg": "会社間を結ぶ専用の直通エレベーター。共用エレベーター(インターネット)に他社の乗客と一緒に乗らず、自社専用のかごで直通する。"}, "gcp-pca-c-q11": {"point": "「各VPCの管理は独立させたまま」で「推移的な経路は不要」ならVPCネットワークピアリング。", "why_asked": "共有VPCとの違い（管理の集中度）と、ピアリングが推移しない（A-B, B-Cがつながっていても自動でA-Cはつながらない）という制約が誤答選択肢の罠になりやすい。", "eg": "2つの会社が専用の内線電話で直接つながるが、それぞれの社内の人事や設備は別会社のまま管理される。相手の取引先の会社(推移先)までは自動的にはつながらない。"}, "gcp-pca-c-q12": {"point": "「外部IPなしのインスタンスから外部へ送信だけしたい」ならCloud NAT。", "why_asked": "Private Google Accessとの混同が典型（どちらも「外部IPなし」の文脈で出るため）。Cloud NATは一般のインターネット向け送信、Private Google AccessはGoogle API宛という宛先の違いを識別させる出題。", "eg": "ホテルの客室電話。フロント(NAT)を経由すれば部屋(インスタンス)から外部へ電話をかけられるが、外部から部屋へ直接かけることはできない。"}, "gcp-pca-c-q13": {"point": "「外部IPなしでGCSやBigQueryなどGoogle APIに到達したい」ならサブネットでPrivate Google Accessを有効化する。", "why_asked": "Cloud NATとの宛先の違い（Google API限定か、一般インターネット全般か）を正確に区別できるかが問われる。要件文に出てくるサービス名（GCS、BigQuery＝Google API）に反応する練習。", "eg": "本社と系列企業を結ぶ専用の社内便。表の郵便局(インターネット)を経由せず、社内ルートだけで書類(データ)がGoogleの各サービスに届く。"}, "gcp-pca-c-q14": {"point": "「L7のDDoSやSQLインジェクションなどWebアプリ層の攻撃から守りたい」ならCloud Armor。", "why_asked": "VPC Service Controlsとの混同（どちらもセキュリティ系のため）。Cloud Armorは着信リクエストへの防御、VPC SCはデータの持ち出し防止という目的の違いを識別させる出題。", "eg": "マンションのオートロックとインターホン。怪しい訪問者は玄関で足止めされ、居住者(バックエンドサーバー)まで到達できない。"}, "gcp-pca-c-q15": {"point": "「保管期間が長く、アクセス頻度が年数回未満」ならArchiveクラスが最安。", "why_asked": "Coldline/Nearlineとの使い分けが頻出。各クラスの想定アクセス頻度（Standard=頻繁、Nearline=月次、Coldline=四半期、Archive=年1回未満）を要件文のアクセス頻度から逆算させる出題。", "eg": "銀行の貸金庫と財布の中身の違い。滅多に出し入れしない権利証(データ)は年会費が安い貸金庫(Archive)へ、毎日使う現金はすぐ取り出せる財布(Standard)に入れる。"}, "gcp-pca-c-q16": {"point": "「水平スケールするリレーショナルDB」で「グローバルな強整合性」と「99.999%級の可用性」が要件ならCloud Spanner。", "why_asked": "Cloud SQLとの混同が典型。Cloud SQLはスケールに上限があり単一リージョン中心なので、グローバル決済のような要件には届かない点を区別させる出題。", "eg": "世界中の空港管制官が同じリアルタイムのフライト情報を見て、矛盾なく離着陸を許可し続けるイメージ。1つの管制塔(単一リージョンDB)だけでは世界規模を支えきれない。"}, "gcp-pca-c-q17": {"point": "「秒間数百万件の書き込み」かつ「シンプルなキー＋カラム構造」ならBigtable。", "why_asked": "BigQueryとの混同が多い（どちらも「大規模データ」を扱うため）。BigQueryは分析(読み取り集計)向け、Bigtableは高速書き込み・低レイテンシ読み出し向けという用途の違いを識別させる出題。", "eg": "高速道路のETCシステム。次々通過する車(データ)を止めずに記録し続ける専用レーンで、後でまとめて渋滞を分析する情報センター(BigQuery)とは役割が違う。"}, "gcp-pca-c-q18": {"point": "「モバイル/Webのオフライン同期」と「リアルタイムリスナー」が要件ならFirestore。", "why_asked": "Spanner（リレーショナル）、Bigtable（大規模時系列）、Memorystore（キャッシュで永続性なし）との用途の切り分けを問う。特にMemorystoreは「DB」ではなくキャッシュである点が誤答の罠。", "eg": "オフィスの伝言板と個人のメモ帳。圏外(オフライン)でも自分のメモ帳に書き留めておき、電波が戻ったら伝言板に自動転記され、他の人ともリアルタイムで共有される。"}, "gcp-pca-c-q19": {"point": "「自動フェイルオーバー」と「読み取り負荷分散」を両方要求されたら、HA構成（リージョナル）とリードレプリカを両方組み合わせる。", "why_asked": "「リードレプリカだけ」を選ばせる誤答が典型的な罠。リードレプリカは読み取り分散はできても自動フェイルオーバーは保証しない、という機能の切り分けを問う出題。", "eg": "テレビ局の生放送。メインキャスターが体調不良で倒れたら即座に副キャスターが引き継ぎ(自動フェイルオーバー)、別チームが過去映像のアーカイブ対応をする(読み取り分散)。役割が分かれている。"}, "gcp-pca-c-q20": {"point": "「ペタバイト級」かつ「サーバーレスでSQL分析」「インフラ管理はしたくない」ならBigQuery。", "why_asked": "Dataproc（クラスタ管理が必要）やCloud SQL（トランザクション処理向け）との役割の違いを、要件文の「インフラ管理はしたくない」というキーワードから見抜けるかを問う出題。", "eg": "図書館で本を借りるのに製本工場を持つ必要がないように、分析したいだけなら基盤(クラスタ)を自分で組み立てなくてよい。"}, "gcp-pca-c-q21": {"point": "「経過日数に応じて自動でクラス変更・削除したい」ならオブジェクトライフサイクル管理ルール。", "why_asked": "手動やスクリプトでの運用は保守性・再現性に欠けるため、宣言的なルール設定で自動化する発想が実務上重要という出題意図。", "eg": "本棚の整理ルールを「1年読まなかった本は倉庫へ、3年読まなかった本は処分」と決めておけば、毎回自分で判断せず自動で片付く。"}, "gcp-pca-c-q22": {"point": "「読み取りが多くDB負荷を減らしたい」かつ「Redis互換のインメモリキャッシュ」が要件ならMemorystore。", "why_asked": "Cloud CDN（静的コンテンツのエッジキャッシュ）との層の違いが誤答の罠。Memorystoreはアプリ〜DB間のデータキャッシュ、CDNはエッジでの配信キャッシュという別レイヤーであることを区別させる出題。", "eg": "会議でよく参照する資料をクラウドの奥深くではなく、手元のメモ帳に控えとして置いておけば、毎回サーバーまで探しに行かずに済む。"}, "gcp-pca-c-q23": {"point": "「セキュリティのベストプラクティス」を問われたら、最小権限のロールを持つサービスアカウントを使い、鍵ファイルのダウンロード・埋め込みは避ける。", "why_asked": "PCAはセキュリティ設問で「動けばよい」設計と「安全に動く」設計の違いを問う。過剰権限のSAや鍵の埋め込みは、動作はしても漏洩・権限昇格のリスクを生む典型的な誤答パターン。", "eg": "アルバイトにはレジ操作の権限だけを与え、経営者用の全店舗の売上データにアクセスできるマスター権限までは渡さない。"}, "gcp-pca-c-q24": {"point": "「組織全体で一律に、プロジェクトごとの個別設定なしに」制約をかけたいなら組織ポリシー（階層継承される構成制約）。", "why_asked": "IAMの拒否ロール（API呼び出しレベルの制御）との違いを問う。組織ポリシーはリソースの「作られ方」自体を構成レベルで制約する点が異なる、という設計レイヤーの区別が出題の核心。", "eg": "学校全体の校則を一度定めれば、新しいクラスができても自動的にその校則が適用され、クラスごとに校則を作り直さなくてよい。"}, "gcp-pca-c-q25": {"point": "「認証情報が漏れてもデータを外部へ持ち出せないようにしたい」というデータ境界の要件ならVPC Service Controls。", "why_asked": "ファイアウォールやCloud Armorとの混同が典型。これらはネットワーク経路やWeb攻撃への防御であり、正規の認証情報を使った正規APIコール経由でのデータ持ち出しは防げない点がVPC SCとの違い。", "eg": "美術館の展示室から、たとえ入館チケット(認証情報)を持っていても、作品(データ)を館外へ持ち出すことはできない仕組みにする。"}, "gcp-pca-c-q26": {"point": "「暗号鍵を自社で管理・ローテーション・無効化したい」というコンプライアンス要件ならCMEK（Cloud KMS）。", "why_asked": "Googleのデフォルト暗号化との違い（顧客が鍵のライフサイクルを制御できるかどうか）を問う。より厳格な要件（鍵の物理的な自社保持）ではCloud EKMが別途候補になる点も周辺知識として押さえておくとよい。", "eg": "自宅の金庫の暗証番号を自分だけが知っていて、必要なら自分の判断で番号を変更したり金庫ごと使用不能にしたりできる。管理会社(Google)に暗証番号を預けきりにしない。"}, "gcp-pca-c-q27": {"point": "「VPNなしで、ユーザーIDとコンテキストに基づいてアクセスを制御したい」ならIdentity-Aware Proxy（IAP）。", "why_asked": "送信元IP制限との違い（IPは持ち運びに弱く、リモートワークやローミングに対応しにくい）を問う。ゼロトラストの考え方（場所ではなくID/コンテキストで信頼判断する）を実装で見分けさせる出題。", "eg": "空港のラウンジ。特定の建物の中にいるかどうかではなく、会員証(ID)を提示できるかどうかで入室を判断する。"}, "gcp-pca-c-q28": {"point": "「事前定義ロールでは権限の粒度が合わない」なら、必要な権限だけを束ねたカスタムロールを作る。", "why_asked": "過剰権限のロール（編集者・オーナー）を安易に付与してしまう誤りを防ぐ出題。事前定義ロールが要件に完全一致しない場合の正しい対処を問う。", "eg": "レストランのアレルギー対応。決まったメニュー(事前定義ロール)にちょうど合う一品がなければ、材料を指定してその人専用の一皿(カスタムロール)を作ってもらう。"}, "gcp-pca-c-q29": {"point": "「GKEのPodからGCP APIへ、鍵ファイルを配布せずに安全にアクセスさせたい」ならWorkload Identity。", "why_asked": "SA鍵をSecretとしてマウントする方式は「動く」が鍵の漏洩・ローテーション管理という運用リスクを抱える。PCAはこの「動くが安全でない」設計をあえて選択肢に混ぜて識別させる。", "eg": "従業員証を紙で印刷して配るのではなく、指紋認証端末を各扉に設置し、本人の指紋そのものが通行証になる仕組みにする。合鍵の複製・紛失のリスクがなくなる。"}, "gcp-pca-c-q30": {"point": "「APIキーやパスワードを集中管理し、バージョン管理・監査・IAM制御をしたい」ならSecret Manager。", "why_asked": "ハードコードや平文保存が漏洩・監査不能という致命的リスクを持つことを実感させ、シークレット管理を専用サービスに任せる設計判断を定着させる出題。", "eg": "家の鍵を玄関マットの下に隠しておくのではなく、誰が持ち出したか記録が残るスマートキーボックスで管理する。"}, "gcp-pca-c-q31": {"point": "「リアルタイム取り込み」「ストリーミング変換」「サーバーレス」がそろったらPub/Sub→Dataflow→BigQueryの組み合わせ。", "why_asked": "サーバーレスのストリーミングETLの定番構成を問う。Cloud SQL直書きやバッチ保存のみでは「リアルタイム分析」という要件を満たせない点を識別させる出題。", "eg": "ベルトコンベアで運ばれてくる荷物を、通過中に検品・仕分けしながら最終的に倉庫の棚(BigQuery)へ自動で収める工場ライン。"}, "gcp-pca-c-q32": {"point": "「既存のHadoop/Sparkジョブをできるだけ改修せずに」移したいならDataproc。", "why_asked": "Dataflowとの使い分け（新規ストリーミングはDataflow、既存Hadoop資産の温存はDataproc）が頻出。移行元資産の有無というキーワードに反応できるかを問う出題。", "eg": "海外赴任で今使っている電化製品をそのまま持っていき、変圧器(マネージド環境)だけ用意してもらって使い続ける。買い替え(書き換え)は現地に慣れてから考える。"}, "gcp-pca-c-q33": {"point": "「日付範囲で絞ることが多く、特定カラムでもよく絞る」というクエリパターンならパーティショニング＋クラスタリングでスキャン量を減らす。", "why_asked": "BigQueryは読み取ったバイト数に応じて課金されるため、SELECT *やフルスキャンがコスト増に直結する。設計段階でスキャン範囲を絞る工夫を問う、コスト最適化の定番出題。", "eg": "宅配便の仕分けセンターで、まず配送先の都道府県(パーティション)ごとに大きく分け、さらに同じ都道府県内は町名順(クラスタリング)に並べておけば、目的の荷物をすぐ見つけられる。"}, "gcp-pca-c-q34": {"point": "「新規のストリーミングETL」で「クラスタ管理をしたくない」ならDataflow。", "why_asked": "Dataprocとの対比で、クラスタという概念自体を持たない完全サーバーレスの処理基盤を選ばせる出題。既存資産の有無が判断の分かれ目になる点はq32で問われた論点と対になる。", "eg": "自分で厨房を持たず、材料を渡すだけで調理してくれるケータリング業者に頼む。新しいメニュー(新規パイプライン)を一から作るときに、厨房設備(クラスタ)を用意する手間がいらない。"}, "gcp-pca-c-q35": {"point": "「同一キーのメッセージを順序保証したい」ならordering keyを指定する。", "why_asked": "Pub/Subは基本的に順序を保証しないメッセージングサービスであるという前提を踏まえた上で、部分的に順序を保証する仕組み（同一キー内限定）を正しく理解しているかを問う出題。", "eg": "工場の生産ラインで、同じ製品番号の部品だけは投入した順番通りに組み立てるが、違う製品番号の部品同士の前後関係までは気にしない。"}, "gcp-pca-c-q36": {"point": "「RTOが数分、RPOが数秒」という極めて厳しい復旧要件で「コストはかかってよい」なら、常時稼働させておくウォームスタンバイ／ホット構成。", "why_asked": "DR戦略（Cold/パイロットライト/ウォームスタンバイ/マルチサイト）はコストと復旧速度のトレードオフになっており、要件文のRTO/RPOの数字からどの段階が必要かを逆算させる出題。", "eg": "病院の緊急手術チーム。呼ばれてから準備を始めるのでは間に合わないので、常にスタンバイ状態(電源オン・機材準備済み)を維持しておく。"}, "gcp-pca-c-q37": {"point": "「信頼性目標を定量管理し、超過分を機能リリースに使いたい」と出たらSLI/SLO/エラーバジェットの枠組み。", "why_asked": "SREの基本サイクルとして頻出。「100%可用性を目指す」という一見正しそうな誤答が、コストや開発速度とのバランスを欠く非現実的な目標である点を見抜かせる出題。", "eg": "家計の予算管理。今月使ってよい上限額(SLO)を決めておけば、まだ余裕があるうちは新しい出費(機能リリース)に回せるし、使い切ったら来月まで節約に回る。"}, "gcp-pca-c-q38": {"point": "「単一リージョン障害でも可用性を保ちたい」が「レイテンシ要件は緩い」ならマルチリージョン（またはデュアルリージョン）バケット。", "why_asked": "可用性とレイテンシはトレードオフの関係にあり、要件文の「レイテンシ要件は緩い」という一文が、コストの高いマルチリージョン構成を選んでよい根拠になっている点を読み取らせる出題。", "eg": "家族写真をスマホだけでなく、離れた実家にも紙焼きを送っておく。自宅が水害にあっても実家の写真は無事、という安心感。ただし取りに行くのに時間はかかってもよい前提。"}, "gcp-pca-c-q39": {"point": "「誤操作から特定時点に戻したい」なら自動バックアップ＋ポイントインタイムリカバリ（PITR）。", "why_asked": "リードレプリカは複製が破損データも追従してしまうため、誤操作からの復旧手段にはならない、という誤答の罠を見抜かせる出題。バックアップ/レプリケーション/リカバリの目的の違いを問う。", "eg": "原稿をこまめにバージョン管理して保存しておけば、書き間違えて上書きしてしまっても、間違える前の版まで戻せる。"}, "gcp-pca-c-q40": {"point": "「1リージョン全断でもサービスを継続したい」なら、複数リージョンにバックエンドを配置しグローバルLBで振り分ける。", "why_asked": "ゾーン分割との違い（ゾーン障害には強くてもリージョン全体の障害には耐えられない）を問う。「リージョン全断」という要件文の粒度に対応する冗長化レベルを選べるかが出題の核心。", "eg": "チェーン店で、ある地域の1店舗が休業しても、他の地域の店舗が営業を続けていればお客さんへのサービス自体は止まらない。"}, "gcp-pca-c-q41": {"point": "「1〜3年安定稼働」で「中断は許容できない」ならSpotではなく確約利用割引（CUD）。", "why_asked": "「コストを抑えたい」という要件文だけを見てSpot VMを選ばせる誤答が典型。中断可否という制約条件を見落とさずに購入オプションを選べるかを問う出題。", "eg": "スマホの通信プランで、都度課金の従量制よりも1年契約の定額プランのほうが総額は安くなる。ただし契約期間中に解約すると損をする、という条件付きの安さ。"}, "gcp-pca-c-q42": {"point": "「最小ダウンタイムでDB移行」かつ「継続的な差分同期」が要件ならDatabase Migration Service。", "why_asked": "一括ダンプ&インポート方式との対比で、切替時のダウンタイムを最小化する仕組み（継続レプリケーション）を選べるかを問う、移行系の定番出題。", "eg": "テレビの生放送を裏で新しいスタジオに同時中継しておき、視聴者に気づかれない一瞬の切り替えでカメラを切り替える。"}, "gcp-pca-c-q43": {"point": "「回線が細く、オンライン転送だと数か月かかる」大容量データの移行ならTransfer Appliance（物理搬送）。", "why_asked": "Storage Transfer Serviceとの使い分けが典型論点。オンライン転送の前提（十分な帯域）が崩れている場合に、物理搬送という選択肢が現実的になる点を問う出題。", "eg": "引っ越しで大量の荷物を、遅い自転車で何十往復もするより、一度トラックをレンタルして丸ごと運んだほうが速い。"}, "gcp-pca-c-q44": {"point": "「アプリ改修なしでそのまま」移行したいならMigrate to Virtual Machines（リフト&シフト）。", "why_asked": "コンテナ化やアプリ書き換えを伴う「近代化」を伴う移行との区別が出題の核心。まずそのまま移してから最適化するという移行の段階論を理解しているかを問う。", "eg": "オフィス移転で、まず今のデスクや棚をそのまま新オフィスに運び込んで営業を再開し、レイアウト変更(近代化)は落ち着いてから検討する。"}, "gcp-pca-c-q45": {"point": "「コストが高く過剰スペック」という状況を「データに基づいて」適正化したいなら、RecommenderとCloud Monitoringの使用率データを見てリサイズする。", "why_asked": "勘や一律の変更ではなく、実測データに基づく意思決定というPCAが重視するコスト最適化の思想を問う出題。", "eg": "スマートウォッチの歩数データを見て、実際の生活パターンに合わせて目標歩数を現実的な数字に見直す。勘ではなく記録に基づいて調整する。"}, "gcp-pca-c-q46": {"point": "「pushをトリガーに自動でビルド〜デプロイまで」を「マネージドで」実現したいならCloud Build。", "why_asked": "自前Jenkinsとの対比で、運用負荷を減らすマネージドサービスの利点を問う。「マネージド」というキーワードへの反応を試す出題。", "eg": "レシピ通りに材料を入れるだけで、あとは全自動でパンを焼いてくれるホームベーカリー。生地作り(ビルド)から焼き上げ(デプロイ)までボタン一つで進む。"}, "gcp-pca-c-q47": {"point": "「宣言的にコードでインフラを管理し、マルチクラウドも見据える」ならTerraform。", "why_asked": "手動構築やスクリプトでは属人化し再現性・監査性に欠ける、という実務でハマりやすいポイントを踏まえた上で、宣言的IaCの標準的な位置づけを問う出題。", "eg": "組み立て家具の説明書。手順を紙に残しておけば、別の人が組み立てても同じ完成形になる。口頭で伝えるだけだと人によって仕上がりが変わってしまう。"}, "gcp-pca-c-q48": {"point": "「メトリクス・ログ・アラートを一元的に」扱いたいならCloud Monitoring＋Cloud Logging＋アラートポリシー。", "why_asked": "個別SSHでの目視確認のような属人的な運用は、規模が大きくなるほど破綻する。可観測性を仕組み化する重要性を問う出題。", "eg": "健康診断の結果を毎回一枚のレポートにまとめてもらい、基準値を超えた項目だけ赤字で警告してくれる仕組み。"}, "gcp-pca-c-q49": {"point": "「承認済みイメージだけをデプロイさせたい」というサプライチェーン統制ならArtifact Registry＋Binary Authorization。", "why_asked": "コンテナサプライチェーンのセキュリティは近年重視される論点。イメージの出所を検証せずにデプロイできてしまう構成のリスクを問う出題。", "eg": "レストランの厨房で、仕入れ業者の検査証明がある食材しか調理に使わないルールを徹底する。出所不明の食材は使わせない。"}, "gcp-pca-c-q50": {"point": "「新バージョンをまず少数のトラフィックに当て、問題なければ徐々に拡大したい」ならカナリアリリース。", "why_asked": "一括置換（ビッグバン）方式のリスクの高さと対比させ、段階的リリースによってリスクを局所化する考え方を問う出題。", "eg": "新商品の試食コーナー。まず少人数に試してもらって評判が良ければ、店頭に大々的に並べる。いきなり全店舗で大量販売はしない。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-c')
  AND q.explanation_data IS NOT NULL;

-- gcp-pca-d
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-d-q1": {"point": "GPUノードにML Podだけを載せたいなら、taintでノードに拒否印を付け、tolerationを持つPodだけ通す。", "why_asked": "taintは特定ノードを拒否する印、tolerationはその拒否を許容してよいという同意で、両者はセットで働く。nodeSelectorだけではGPUノード側は誰でも受け入れてしまい、通常のWeb Podが紛れ込んでGPUを無駄に占有する事故が起きやすいため、GKEの設計問題で頻出する。", "eg": "工事現場の立入禁止テープ(taint)は、特別な許可証(toleration)を持つ作業員だけがくぐれるようになっている。"}, "gcp-pca-d-q2": {"point": "イベントで起動し使った分だけ課金される小さな処理には、常時稼働のサーバーではなくCloud Functionsを選ぶ。", "why_asked": "常時稼働のGCEやGKE、App Engine Flexibleは待機中もコストが発生し続ける。数十行の単発処理のためにサーバーを常駐させるのはコスト効率が悪いという判断力を、PCAはよく問う。", "eg": "宅配ボックスは荷物が届いた瞬間だけ動き、普段は電源をほとんど使わない。"}, "gcp-pca-d-q3": {"point": "処理中のメモリ上データまで暗号化しハイパーバイザからも隠したいなら、Confidential VMを選ぶ。", "why_asked": "保存時と通信時の暗号化は標準で効いているが、計算中に復号された状態のデータはハイパーバイザから見えてしまうことがある。この使用中(in use)の穴を埋める技術という整理を理解しているか、シールドVM(起動整合性の保護)との混同も含めて問われる。", "eg": "手紙は郵送中も保管中も守られているのに、開封して読んでいる最中だけ覗き見される、という穴を塞ぐようなもの。"}, "gcp-pca-d-q4": {"point": "同じテンプレートから量産しつつ複数ゾーンに配って冗長性も持たせたいなら、リージョンMIGを選ぶ。", "why_asked": "ゾーンMIGは自動修復やオートスケールができても単一ゾーン内に閉じるため、そのゾーンが落ちると全滅する。複数ゾーンへ自動分散する構成を可用性設計の基本として選べるかが問われる。", "eg": "同じ設計図の店舗を1つの商店街だけに並べると、その商店街が停電したら全店休業になる。複数の街に分けて出店する発想。"}, "gcp-pca-d-q5": {"point": "CPU以外の業務指標(キュー長など)で増減させたいなら、カスタム指標ベースのオートスケーラを設定する。", "why_asked": "CPU使用率は必ずしも実際の負荷を表さない。Pub/Subの未処理メッセージが溜まっていてもCPUは低いままということがあり、CPU一辺倒のスケーリング設計だと処理遅延に気づけないという実務の落とし穴がよく問われる。", "eg": "レジの混雑を店員の疲労度で測るのでなく、実際に並んでいる客の人数で測る方が正確。"}, "gcp-pca-d-q6": {"point": "コールドスタートを避けたいなら、最小インスタンス数を設定して常時いくつかを温めておく。", "why_asked": "Cloud Runはデフォルトで未使用時にゼロまでスケールインしコストは下がるが、次のリクエストでコンテナ起動待ち(コールドスタート)が発生する。急なトラフィックとレイテンシ要件を両立させる設定を知っているかが問われる。", "eg": "開店前から数人のスタッフを待機させておけば、開店直後に客が来てもすぐ対応できる。"}, "gcp-pca-d-q7": {"point": "オンプレとGCPの経路を手動更新なしに自動反映させたいなら、Cloud RouterでBGPを使う。", "why_asked": "スタティックルートはオンプレ側でネットワーク変更があるたびにGCP側も手動で直す必要があり、変更漏れによる通信断のリスクがある。VPNやInterconnectと組み合わせて動的ルーティングを構成できるかが実務でもよく問われる。", "eg": "カーナビが新しい道路情報を自動で受信して経路に反映するのに対し、紙の地図は誰かが手で書き直さない限り古いままになる。"}, "gcp-pca-d-q8": {"point": "組織/フォルダ単位で一括のファイアウォールガードレールを配下に継承させたいなら、階層型ファイアウォールポリシーを選ぶ。", "why_asked": "各VPCで個別にルールを設定する運用は、プロジェクトが増えるほど抜け漏れが起きやすい。組織全体で最低限守らせたいルールを上位から強制する設計は大規模組織のガバナンス課題として頻出で、Cloud Armor(L7 Web防御)や組織ポリシー(構成の制約)との役割の違いも問われる。", "eg": "本社が定めた最低限の防犯ルールを全支店に一律で効かせ、各支店が個別に緩めることはできないようにするようなもの。"}, "gcp-pca-d-q9": {"point": "サードパーティのマネージドサービスにパブリックIPを経由せず内部IPで繋ぎたいなら、Private Service Connectを選ぶ。", "why_asked": "VPCピアリングはIPレンジ重複や推移的接続の制約があり、不特定多数のサービス提供者と消費者を繋ぐ用途には向かない。PSCは消費側VPC内にエンドポイントを置くだけで済むためパートナー接続やSaaS連携の設計でよく問われ、送信専用のCloud NATとの役割の違いも混同ポイントになる。", "eg": "表の道路(パブリックインターネット)に出ずに、ビルの中の専用エレベーターで直接相手の会社のフロアに行けるようにする仕組み。"}, "gcp-pca-d-q10": {"point": "多数の拠点をハブ&スポークで一元管理したいなら、Network Connectivity Centerを選ぶ。", "why_asked": "VPCピアリングをフルメッシュで組むと拠点数の二乗で接続数が増え、管理も経路制御も破綻する。ハブに集約する設計へ切り替える判断が、大規模ネットワーク設計の頻出パターン。", "eg": "全都市間を直行便で結ぼうとすると路線が爆発的に増えるが、空港をハブにして乗り継ぎにすれば路線数を抑えられる。"}, "gcp-pca-d-q11": {"point": "オンプレとGCPの名前解決を双方向にしたいなら、転送ゾーンやインバウンド・アウトバウンドフォワーディングを組む。", "why_asked": "ハイブリッド環境ではGCP側がオンプレの内部ドメインを、オンプレ側がGCPのプライベートゾーンを、それぞれ解決できないとサービス間通信を名前で組めない。片方向だけの設定漏れが実務でよく起きるため、双方向の構成を理解しているかが問われる。", "eg": "自社の内線電話帳と取引先の内線電話帳をお互いに参照できるよう、交換台同士をつなぐようなもの。"}, "gcp-pca-d-q12": {"point": "同一リージョン内部限定でL7のパスベースルーティングをしたいなら、内部アプリケーションロードバランサを選ぶ。", "why_asked": "外部向けLBを内部用途に使うと不要な公開範囲を作ってしまい、外部ネットワークLBはL4止まりでパスベースの振り分けができない。要件(内部限定・L7)に過不足のない構成を選べるかが問われる。", "eg": "社内専用の受付窓口が、来客の用件(URLのパス)ごとに担当部署へ案内するが、社外からは受付自体に入れないようなもの。"}, "gcp-pca-d-q13": {"point": "世界中に配る静的コンテンツを速く低負荷で配信したいなら、グローバル外部LB+Cloud CDNでエッジキャッシュする。", "why_asked": "単一リージョンから配信すると遠方のユーザーほど遅延が大きく、アクセス集中時は元サーバーに負荷が集中する。CDNでエッジにキャッシュを分散させる設計はグローバル配信の基本として頻出し、Memorystore(インメモリDBキャッシュ)との階層の違いも混同されやすい。", "eg": "人気商品を各地のコンビニにも置いておけば、客はわざわざ本社倉庫まで買いに行かずに済む。"}, "gcp-pca-d-q14": {"point": "どのFWルールがどの通信を許可/拒否したか記録したいなら、ファイアウォールルールロギングを使う。", "why_asked": "VPCフローログは通信量の可視化が主目的で、どのルールが判定したかまでは特定しにくい。不要な許可ルールの棚卸しにはルール単位のログが要るという、ログの種類ごとの役割分担を理解しているかが問われる。", "eg": "門番がどの規則に基づいて誰を通したかを記録に残せば、後から不要な通行許可を洗い出せる。"}, "gcp-pca-d-q15": {"point": "PostgreSQL互換のまま標準Cloud SQLより高性能・高スケールが欲しいなら、AlloyDBを選ぶ。", "why_asked": "Spannerはグローバル分散・強整合に強いがPostgreSQL完全互換ではなく、大掛かりな移行を伴う。互換性を保ったまま性能だけ引き上げたいという中間的な要件を満たす選択肢を見分けられるかが問われる。", "eg": "同じ車種のボディのまま、エンジンだけ高性能版に積み替えるようなもの。"}, "gcp-pca-d-q16": {"point": "Bigtableの書き込みが偏るなら、まず行キーが連番やタイムスタンプ先頭になっていないかを疑う。", "why_asked": "Bigtableは行キーの辞書順で物理的に分割配置されるため、連番やタイムスタンプ先頭のキーは新しい書き込みが常に同じ範囲に集中し、そのノードだけ過負荷になる。キー設計の失敗は本番で気づきにくく実害が大きいため、原因の見分け方が頻出。", "eg": "出席番号の若い順に1つの受付窓口へ並ばせると、その窓口だけ長蛇の列になるようなもの。"}, "gcp-pca-d-q17": {"point": "定常的に大量利用してコストを固定額にしたいなら、スロット予約(容量ベース/Editions)を検討する。", "why_asked": "オンデマンド課金はスキャン量に応じて変動しアドホックな利用には向くが、大量かつ継続的なクエリでは予測しにくい高額請求のリスクがある。利用パターンに応じた課金方式の使い分けが、コスト最適化の観点で頻出。", "eg": "電気を都度の従量制で使うのでなく、大口利用者向けの定額契約に切り替えるようなもの。"}, "gcp-pca-d-q18": {"point": "オンプレDBの変更をサーバーレスでほぼリアルタイムに取り込みたいなら、Datastreamで変更データキャプチャ(CDC)を使う。", "why_asked": "日次バッチの全件再ロードは鮮度が低くデータ量が増えるほど非効率になる。変更差分だけを継続的に流すCDCという考え方と、それをサーバーレスで実現する具体的なサービスを結びつけられるかが問われる。", "eg": "本を毎日まるごと書き写すのでなく、書き換わったページだけ差し替えていくようなもの。"}, "gcp-pca-d-q19": {"point": "複数VMから同時に読み書きできる共有NFSが必要なら、Filestoreを選ぶ。", "why_asked": "Persistent Diskは基本的に単一VMへのアタッチが前提で複数書き込み共有には向かず、Cloud StorageはNFSのようなファイルシステム互換の挙動を持たない。レガシーアプリが共有マウント前提で作られている場合の移行先として頻出。", "eg": "複数の部署が同時にアクセスできる社内共有フォルダのようなもの。"}, "gcp-pca-d-q20": {"point": "アカウントを発行せず期限付きで一時アクセスさせたいなら、署名付きURLを発行する。", "why_asked": "バケット全公開は無関係な第三者にもアクセスを許してしまい、IAMロール付与やSAキーの受け渡しは恒久的な権限で管理コストと漏洩リスクが高い。外部パートナーへの一時アクセス許可という要件に過不足のない手段を選べるかが問われる。", "eg": "期限が来たら自動的に無効になる、来訪者用の一時入館証のようなもの。"}, "gcp-pca-d-q21": {"point": "管理者ですら削除できない不可逆な保管をしたいなら、保持ポリシー+バケットロックを使う。", "why_asked": "IAMで削除権限を絞るだけでは、その設定自体を後から誰かが変更・解除できてしまい規制対応(WORM要件)を満たせない。バケットロックはポリシー自体を凍結して緩和も削除もできなくする点が、規制業界のPCA出題で重要な区別。", "eg": "タイムカプセルを溶接して、決めた年まで誰にも開けられなくするようなもの。"}, "gcp-pca-d-q22": {"point": "複数リージョンで高可用性と低レイテンシ読み取りを両立したいなら、Spannerのマルチリージョン構成を選ぶ。", "why_asked": "シングルリージョン構成はそのリージョン障害で全体が止まるうえ、遠隔地のユーザーには読み取りレイテンシが大きい。地理的に分散したレプリカを持ちながら強整合を保つというSpannerの特性を理解しているかが問われる。", "eg": "主要都市それぞれに支店を置けば、客は近くの支店で対応してもらえ、1店が休業しても他店で業務が続く。"}, "gcp-pca-d-q23": {"point": "特定の時間帯や特定リソースだけに権限を絞りたいなら、IAM Conditionsを使う。", "why_asked": "通常のロール付与は付与された瞬間から常時・全対象リソースに効いてしまう。一時的な作業や特定リソースだけに絞った最小権限を実現する仕組みとして、条件付きロールバインディングが実務でもよく使われる。", "eg": "入館証を、平日の日中だけ・特定のフロアだけ有効にするようなもの。"}, "gcp-pca-d-q24": {"point": "長期のSAキーを発行せず短時間だけ別SAの権限を借りたいなら、サービスアカウントのなりすまし(impersonation)を使う。", "why_asked": "SAキーのJSONファイルは漏洩すると無期限に悪用され得る重大なリスクで、多くのセキュリティ監査で発行自体を避けるよう求められる。CIパイプラインの一時的な昇格権限という典型シナリオで、鍵を発行せず短命トークンを使う設計を選べるかが問われる。", "eg": "合鍵を作って渡すのではなく、必要な時だけ使える時限式のワンタイム鍵を発行してもらうようなもの。"}, "gcp-pca-d-q25": {"point": "上位でどれだけ広い権限が許可されていても特定操作だけは拒否したいなら、IAM Denyポリシーを使う。", "why_asked": "allowロールを個別に外すだけでは、別の継承経路やグループ経由で同じ権限が残ってしまうことがある。Denyはallowより優先して評価されるため、機微な操作を組織全体で確実に禁止するガードレールとして重要。", "eg": "全館共通の入館証を持っていても、核心部の部屋だけは別の赤いゲートで誰も通さないようにするようなもの。"}, "gcp-pca-d-q26": {"point": "全社ルールは保ちつつ一部チームだけ例外を認めたいなら、下位階層でポリシーを上書き/マージして例外を設定する。", "why_asked": "組織ポリシー自体を削除すると全社的なガードレールを失ってしまう。階層構造の中で上位の制約を維持したまま特定のフォルダ/プロジェクトだけ例外を設定できるという継承の仕組みを理解しているかが問われる。", "eg": "全社共通の服装規定は保ったまま、特定の部署だけ私服可という例外を出すようなもの。"}, "gcp-pca-d-q27": {"point": "データだけでなく運用担当者の所在地まで規制に合わせて統制したいなら、Assured Workloadsを使う。", "why_asked": "単なるリージョン制限の組織ポリシーはデータの置き場所しか縛れず、サポート担当者の所在地や利用可能な機能の制限までは対応できない。金融・政府系など厳格なコンプライアンス要件のシナリオで、統制の粒度の違いを見分けられるかが問われる。", "eg": "金庫の設置場所だけでなく、その金庫を扱える行員の勤務地や国籍まで規定するようなもの。"}, "gcp-pca-d-q28": {"point": "暗号鍵の実体をGoogleの外(オンプレやサードパーティHSM)に置いたままGCPリソースを暗号化したいなら、Cloud EKMを使う。", "why_asked": "CMEKはGoogle Cloud KMS内で顧客が鍵を管理するが、鍵マテリアル自体はGoogleのインフラ内にある。鍵をGoogleに一切預けたくないという強い統制要件はEKMでしか満たせず、CMEKとの区別が実務でもよく問われる。", "eg": "貸金庫の鍵を銀行に預けるのでなく、自宅の別の金庫に保管しておくようなもの。"}, "gcp-pca-d-q29": {"point": "大量データからクレジットカード番号や個人情報を自動検出・マスキングしたいなら、Cloud DLP(Sensitive Data Protection)を使う。", "why_asked": "自前の正規表現は検出パターンの網羅性が低く新しい形式のPIIに追従できない。多数の検出器を組み込んだ専用サービスで検出・匿名化までまとめて行うという実務の定石を知っているかが問われる。", "eg": "大量の書類の山から個人情報の部分だけを自動で見つけ、黒塗りしてくれる道具のようなもの。"}, "gcp-pca-d-q30": {"point": "設定ミス・脆弱性・脅威を組織横断で一元的に可視化し優先度付けしたいなら、Security Command Centerを使う。", "why_asked": "各サービスのログを個別に見る運用は、組織が大きくなるほど見落としが増え全体像を把握できなくなる。散在するリスクを一箇所に集約し優先順位をつけて対応するという、大規模組織のセキュリティ運用の基本設計が問われる。", "eg": "病院の集中監視室のように、各病室の異常を一括で見て緊急度の高い順に対応するようなもの。"}, "gcp-pca-d-q31": {"point": "依存関係のあるバッチ処理をDAGとして記述しスケジュール・リトライ・監視したいなら、Cloud Composer(マネージドAirflow)を使う。", "why_asked": "Cloud Schedulerは単発のジョブ起動が主目的で、ジョブ間の依存関係(このタスクが終わったら次を実行、失敗したらリトライ)までは表現できない。複雑な依存関係を持つETLのオーケストレーションという要件に対して、適切なツールの守備範囲を見分けられるかが問われる。", "eg": "下ごしらえ→加熱→盛付という料理の手順書を自動で順番に進め、途中で失敗したらそこからやり直すようなもの。"}, "gcp-pca-d-q32": {"point": "散在するデータを横断的に発見・分類・統制したいなら、Dataplexを使う。", "why_asked": "スプレッドシートでの台帳管理や各チームへの任せきりは、データが増えるほどどこに何があるか誰も把握できなくなる。組織全体のデータガバナンスを仕組み化する必要がある場面で、専用サービスの役割が問われる。", "eg": "各部署がバラバラに持っている書庫を横断的に目録化し、貸出ルールを敷く図書館システムのようなもの。"}, "gcp-pca-d-q33": {"point": "同じ集計クエリが繰り返し実行されるなら、マテリアライズドビューで結果を事前計算して使い回す。", "why_asked": "毎回フルスキャンでクエリを実行するとダッシュボードのたびにレイテンシとコストが発生する。集計結果をキャッシュ・自動更新して再利用するという発想は、BigQueryのコストと速度の両方を最適化する定石として頻出。", "eg": "毎回家計簿を一から集計し直すのでなく、月次合計を一度メモしておいて使い回すようなもの。"}, "gcp-pca-d-q34": {"point": "変換が不要なら、Pub/SubのBigQueryサブスクリプションで中間処理なしに直接書き込む。", "why_asked": "変換が必要ならDataflowを挟む設計が適切だが、変換不要なケースにまでDataflowを挟むのは構成もコストも過剰になる。要件に応じて何も挟まないという選択肢を取れるかが問われる。", "eg": "そのまま使える荷物は仕分け倉庫を通さず直送するようなもの。"}, "gcp-pca-d-q35": {"point": "指標定義を一元化したセルフサービスBI・埋め込み分析・ガバナンスが要るなら、Looker(LookML)を選ぶ。", "why_asked": "Looker Studioは手軽に使えるが、指標(メトリクス)の定義を一箇所に集約して全社で同じ数字を見せるというセマンティックモデルの機能は弱い。エンタープライズ規模でのBI選定は、手軽さとガバナンスのどちらを優先するかの見極めが問われる。", "eg": "全社で売上の定義を一つに統一し、誰がどの部署で出しても同じ数字になるようにするようなもの。"}, "gcp-pca-d-q36": {"point": "本番投入前はピーク時の必要量を見積もり、不足するquotaは事前に増加申請しておく。", "why_asked": "quotaはプロジェクト/リージョンごとに上限があり無制限ではない。ローンチ後にエラーで気づく事後対応はサービス停止に直結するため、キャパシティプランニングを設計の初期段階に組み込む姿勢がPCA試験で重視される。", "eg": "イベント前に椅子の数を見積もり、足りなければ前もって追加発注しておくようなもの。"}, "gcp-pca-d-q37": {"point": "コントロールプレーン自体をゾーン障害に強くしたいなら、リージョンクラスタを選ぶ。", "why_asked": "ノードを増やしてもワーカーの冗長性は上がるが、クラスタを制御するコントロールプレーンが単一ゾーンに留まっていればそこが落ちたときに管理操作ができなくなる。ワーカーノードの冗長化とコントロールプレーンの冗長化は別問題という区別が頻出。", "eg": "指令室を1室に置くのでなく複数拠点に分けておけば、1拠点が停電しても指揮が止まらないようなもの。"}, "gcp-pca-d-q38": {"point": "ゾーン障害でもデータ損失ゼロ(RPO=0)かつ強整合が必須なら、Spannerの同期レプリケーションを選ぶ。", "why_asked": "日次バックアップはその時点までしか復元できずRPOが大きく、単一ゾーン構成はゾーン障害でデータそのものを失うリスクがある。書き込み確定と複製完了を同期させることでRPO=0を実現するという仕組みの理解が、ミッションクリティカルなDB選定で問われる。", "eg": "書いた瞬間に控えにも同時記録しておけば、片方の帳簿が消えても内容は無事に残るようなもの。"}, "gcp-pca-d-q39": {"point": "繰り返す手作業はtoilとして計測し自動化する、障害は人でなく仕組みを直す非難なきポストモーテムで振り返る、がSREの健全な文化。", "why_asked": "人を増やして手作業を続けたり担当者を叱責したりする対応は、根本原因を放置したまま同じ問題を再発させ、心理的安全性を損なって問題の報告自体を萎縮させる。PCAはアーキテクチャだけでなく組織運用の設問も出るため、SREの基本姿勢が問われる。", "eg": "同じ場所で転ぶ人が続くなら、その人を叱るより地面の段差そのものを直す方が再発を防げるようなもの。"}, "gcp-pca-d-q40": {"point": "調子の悪いバックエンドを自動で切り離し健全な方へ寄せたいなら、ヘルスチェック+アウトライア検出を組む。", "why_asked": "手動での切り離しは検知から対応までに時間がかかり、その間ユーザーはエラーを受け続ける。異常なバックエンドを自律的に検知・隔離する仕組みは、可用性の高いLB設計の基本として頻出。", "eg": "発熱した店員を自動的に裏に下げ、元気な店員に接客を回すようなもの。"}, "gcp-pca-d-q41": {"point": "チーム・サービス・環境ごとにコストを按分し詳細分析もしたいなら、リソースにラベルを付けBillingをBigQueryにエクスポートする。", "why_asked": "請求コンソールの合計表示だけではどのチームがいくら使ったかが分からず、コスト最適化の議論が進まない。ラベルという分類の仕組みと、明細をデータ化してSQLで自由に切り分けるという発想の組み合わせが、コスト管理の定石として頻出。", "eg": "レシートに部署名を書いておき、家計簿アプリで部署別に集計するようなもの。"}, "gcp-pca-d-q42": {"point": "使いすぎる前に検知して通知・自動アクションに繋げたいなら、予算(Budget)としきい値アラートを設定する。", "why_asked": "予算アラートはあくまで通知であり、しきい値を超えても自動的に課金や利用を停止するわけではないという誤解が実務でもよくある。自動停止したい場合はPub/Sub連携で別途アクションを組む必要がある点が、混同されやすいポイントとして問われる。", "eg": "口座残高が一定額を切ったらスマホに通知が来るよう設定しておくようなもの。"}, "gcp-pca-d-q43": {"point": "部門ごとにポリシー・課金・アクセスを分離しつつ全体を統制したいなら、まず組織→フォルダ→プロジェクトのリソース階層を設計する。", "why_asked": "1つのプロジェクトに全部集約すると権限や課金の分離ができず、逆に無秩序にプロジェクトを量産すると統制が効かなくなる。大企業のガバナンス設計では、階層構造をまず整えてからIAMやポリシーを継承させるという順序がPCA試験で重視される。", "eg": "本社→事業部→案件という組織図をまず整えてから、規則を上から下へ継がせていくようなもの。"}, "gcp-pca-d-q44": {"point": "中断されても困らないバッチはSpot VMのノードプールに、止められない重要Podは通常ノードプールに分けて配置する。", "why_asked": "全ノードをSpotにするとコストは下がるが、重要なワークロードまで中断リスクに晒してしまう。ワークロードの性質(中断耐性の有無)に応じてノードプールを使い分けるという設計判断が、コストと信頼性の両立を問うPCA典型パターン。", "eg": "使い捨てで構わない作業は格安のアルバイトに任せ、絶対に止められない仕事は正社員が担うようなもの。"}, "gcp-pca-d-q45": {"point": "継続利用は見込めるがマシン構成が変わりうるなら、支出ベースの柔軟な確約利用割引(flexible CUD)を検討する。", "why_asked": "特定マシンタイプに縛られる固定CUDは同じ構成を長期間使い続ける場合には最も割安になるが、構成が変わる可能性がある場合は割引を活かせずロックインのリスクを負う。利用の確実性と柔軟性のトレードオフを見極める判断が問われる。", "eg": "具体的な品目は決めずに月にいくら買うかだけ約束して割引をもらう契約のようなもの。"}, "gcp-pca-d-q46": {"point": "ゾーン障害への耐性は、計算層をリージョンMIGで複数ゾーンに分散し、DB層はCloud SQLのHA(リージョナル)構成で自動フェイルオーバーさせる、の組み合わせで実現する。", "why_asked": "三層アプリの可用性設計では計算層とデータ層それぞれに別々の冗長化手段が必要で、片方だけ対策しても全体の可用性は上がらない。複数の正解を選ばせる設問形式で、対策の抜け漏れがないかを見る出題が多い。", "eg": "店舗を複数の地区に分けて構え、金庫番にも控えを用意しておけば、どちらか片方が倒れても営業を続けられるようなもの。"}, "gcp-pca-d-q47": {"point": "SA運用で避けるべきは、鍵を公開の場所に置くことと、必要以上の強い権限を渡すことの2つ。", "why_asked": "SAキーのリポジトリへのコミットは漏洩事故の典型パターンで、一度公開リポジトリに載ると検索ボットに拾われ悪用されるまでが早い。全SAへのOwner付与は最小権限の原則に真っ向から反する。両方とも実際のセキュリティインシデントで頻出する原因のため、アンチパターンとして明確に見分けられるかが問われる。", "eg": "マスターキーを掲示板に貼り出したり、全員に無条件で配ったりするのは論外、というようなもの。"}, "gcp-pca-d-q48": {"point": "大量時系列の低レイテンシ取り込み・急増吸収・後の大規模分析には、Pub/Subでバッファ、Dataflowでストリーム処理、Bigtableに時系列保存・BigQueryで分析、という定石構成にする。", "why_asked": "車両からのテレメトリのような大量・高頻度の書き込みをCloud SQLのようなリレーショナルDBに直接受けると、書き込みがボトルネックになりすぐに詰まる。取り込みの急増を吸収するバッファ層と、目的別に最適化されたストレージを使い分けるという、IoT/ストリーミングアーキテクチャの定石パターンが頻出。", "eg": "工場に流れ込む大量の部品を、いったんバッファに溜めてから流しながら検品し、すぐ使う倉庫と分析用の倉庫の両方に振り分けるようなもの。"}, "gcp-pca-d-q49": {"point": "所在地規制・鍵の自社統制・ゼロトラストアクセス・PII検出/マスキングの4要件は、それぞれAssured Workloads・CMEK/EKM・IAP・Cloud DLPを組み合わせて満たす。", "why_asked": "医療データのような複合的なコンプライアンス要件は、単一のサービスではすべてをカバーできないことが多い。要件を分解し、それぞれに対応する専用サービスを正しく紐づけられるかという、PCA試験らしい統合的な設計力が問われる。", "eg": "金庫の置き場所の規制、鍵の自社管理、入室時の本人確認、書類の黒塗りを、それぞれ専門の仕組みで一式そろえるようなもの。"}, "gcp-pca-d-q50": {"point": "世界規模の低レイテンシ・オートスケール・グローバル強整合・単一IPを全部満たすには、複数リージョンのGKE/Cloud Runをグローバル外部LB(単一IP)でまとめ、データはCloud Spannerで強整合を保つ。", "why_asked": "単一リージョンや単一インスタンスの構成は、要件のどれか(地理的な低レイテンシ、ゾーン/リージョン冗長、グローバルな強整合)を必ず落としてしまう。複数の要件を同時に満たす統合的なアーキテクチャを組み立てられるかという、PCA試験の総合問題としての典型。", "eg": "世界共通の受付を一つ用意して各地の最寄り拠点に案内しつつ、どの拠点で確認しても同じ内容の成績表を見せられるようにするようなもの。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-d')
  AND q.explanation_data IS NOT NULL;

-- gcp-pca-e
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-e-q1": {"point": "ノード運用をGoogleに任せてPod単位で払いたいならAutopilot、ノード設定を自分で細かく制御したいならStandardを選びます。", "why_asked": "ノード管理の負荷を軽視してStandardを選び、パッチ適用やスケール設計に想定外の工数を取られる失敗が実務で起きやすいところです。運用モデルの違いを要件文から読み取れるかが問われます。", "eg": "レンタカーなら整備やオイル交換は貸主任せで、乗った分だけ払えば済みます。自分の車を持つと整備は全部自分でやる必要がある、その違いに近いです。"}, "gcp-pca-e-q2": {"point": "実行して完了する処理ならジョブ、リクエストを待ち受け続ける処理ならサービスを選びます。", "why_asked": "バッチ処理を誤ってサービスとして立ててしまうと、ヘルスチェックが失敗したり不要な待受課金が発生したりします。run-to-completion型と常駐型の見分けが実務でつまずきやすい点です。", "eg": "洗濯機の一回の洗濯コースは回したら終わりますが、換気扇は電源を入れている間ずっと回り続けます。その違いに近いです。"}, "gcp-pca-e-q3": {"point": "コア単位ライセンス(BYOL)のように物理CPUの専有が条件のソフトを動かすならSole-tenantノードを選びます。", "why_asked": "通常のGCEは複数の利用者でハードウェアを共有するため、物理専有を前提とするライセンス契約と食い違います。この前提の違いに気づかず通常のGCEを選ぶと、ライセンス監査で問題になる実務の落とし穴です。", "eg": "音楽ライブで他の客と席を共有せず、フロア全体を貸し切るVIP席を用意するようなものです。"}, "gcp-pca-e-q4": {"point": "無停止で段階的に切り替えたい、問題があっても被害を一部に抑えたいならローリング更新(surge/canary)を選びます。", "why_asked": "一斉置換は手軽に見えても、本番障害が起きたときに全台へ被害が及びます。可用性要件から更新戦略を選ばせる典型的な出題パターンです。", "eg": "新メニューをいきなり全店舗に出すのではなく、まず1店舗で試験販売してから他店に広げるようなものです。"}, "gcp-pca-e-q5": {"point": "署名・検証済みのイメージしか本番に入れたくないならBinary Authorizationを選びます。", "why_asked": "レジストリを非公開にするだけでは、中に置かれたイメージが承認済みかどうかまでは検証できません。デプロイの瞬間に中身をチェックするゲートの必要性が、サプライチェーン攻撃対策として問われます。", "eg": "受付で身分証を確認するだけでなく、持ち込む荷物そのものに検品済みのシールが貼ってあるか入口で確かめるようなものです。"}, "gcp-pca-e-q6": {"point": "コンテナに加えて言語パッケージも一元管理し、リージョン指定や脆弱性スキャンまで使いたいならArtifact Registryを選びます。", "why_asked": "Container Registryの後継サービスであり、今の標準はArtifact Registryだという前提知識と、マルチフォーマット対応や地域指定といった機能差を問う形で出やすいところです。", "eg": "荷物の種類ごとに別々の倉庫を借りていたのを、一つの総合倉庫にまとめて棚ごとに仕分けるようなものです。"}, "gcp-pca-e-q7": {"point": "既存のVMワークロードをそのままGKE上のコンテナへ移したいならMigrate to Containersを選びます。", "why_asked": "モダナイズの第一歩として全部書き直す方法を選びがちですが、期間やコストの制約がある移行案件では自動変換ツールを知っているかどうかで工数が大きく変わります。", "eg": "家をまるごと解体して建て直すのではなく、家財道具を規格箱に詰め替えて新居へ運ぶだけで済ませるようなものです。"}, "gcp-pca-e-q8": {"point": "ネットワークは中央で一元管理しつつ各チームが自分のプロジェクトでリソースを作りたいならShared VPCを選びます。", "why_asked": "独立VPCを全結合でピアリングする方法は一見柔軟に見えても、接続数が増えるほど管理項目が組み合わせ的に膨らみます。中央統制と分散開発を両立する標準パターンとして問われます。", "eg": "各部屋がそれぞれ電気工事業者を呼ぶのではなく、ビル全体の配線は管理会社が一括で敷き、各部屋はコンセントを挿すだけにするようなものです。"}, "gcp-pca-e-q9": {"point": "認証情報が漏れてもデータを境界の外へ持ち出されたくないならVPC Service Controlsを選びます。", "why_asked": "IAMは誰が操作できるかを制御しますが、盗まれた認証情報を悪用された場合はIAMだけでは止められません。このIAMの限界を理解しているかが実務でも試験でも問われる典型ポイントです。", "eg": "家の鍵を盗まれても、敷地の外に大きな荷物を持ち出せないよう門で毎回確認する警備員を置くようなものです。"}, "gcp-pca-e-q10": {"point": "Webアプリへの攻撃やDDoS、地域からのアクセスをエッジで防ぎたいならCloud Armorを選びます。", "why_asked": "ファイアウォールルールはIPやポート単位の制御であり、SQLインジェクションのようなアプリケーション層の攻撃までは防げません。このレイヤーの違いを混同しないことが問われます。", "eg": "郵便局が封筒の宛先だけでなく、中身に不審物が入っていないかまで検査するようなものです。"}, "gcp-pca-e-q11": {"point": "VPNを使わずID・デバイス・場所などの文脈で社内アプリへのアクセスを許可したいならIAPを選びます。", "why_asked": "従来のVPNは境界の内と外を分ける防御なので、リモートワークで境界が曖昧になると弱点になります。BeyondCorpと呼ばれるゼロトラストの考え方の中核として問われます。", "eg": "ホテルでフロントを通過しただけでは各部屋に入れず、部屋ごとにカードキーで毎回本人確認するようなものです。"}, "gcp-pca-e-q12": {"point": "十分な帯域とコロケーション設備があり、高帯域・低レイテンシ・SLA付きの専用線が欲しいならDedicated Interconnectを選びます。", "why_asked": "専用線というキーワードだけでVPNと混同しやすいですが、VPNはインターネット経由のためSLAや帯域保証が弱いです。設備要件があるかどうかでDedicatedかPartnerかを選び分ける判断が問われます。", "eg": "一般の電話回線と、自社専用に敷いた占有回線との違いに近いです。"}, "gcp-pca-e-q13": {"point": "外部IPなしで送信だけしたい、受信は不要という要件ならCloud NATを選びます。", "why_asked": "インターネットに出たいなら外部IPを付ければよいという短絡的な発想は、受け口を不必要に増やしてしまいます。送信専用の要件では最小権限の原則に沿ってNATを選ぶ判断が問われます。", "eg": "郵便ポストには投函できても、外から中身を取り出すことはできません。それに近い一方通行の仕組みです。"}, "gcp-pca-e-q14": {"point": "外部IPなしでGoogle APIに到達したいならPrivate Google Accessをサブネットで有効化します。", "why_asked": "Cloud NATと役割が重なって見えますが、NATは汎用のインターネットへの送信経路、Private Google AccessはGoogleサービス専用の内部経路という違いを理解しているかが問われます。", "eg": "外部に出す一般の郵便とは別に、社内便としてGoogle宛だけに直接届く内部の配達ルートがあるようなものです。"}, "gcp-pca-e-q15": {"point": "単一リージョンで完結し多少のレイテンシ最適化は妥協できるなら、コストを抑えるStandardティアを検討します。", "why_asked": "Premiumの方が高性能だから常に良いという思い込みでコストを見落としがちですが、要件がグローバルな低レイテンシを求めていないかを読み取れるかがコスト最適化の判断材料になります。", "eg": "同じ市内への配達なら速達を使わず普通郵便で十分、という考え方に近いです。"}, "gcp-pca-e-q16": {"point": "アクセス元の地域などに応じてDNSの応答を出し分けたいならCloud DNSのルーティングポリシーを選びます。", "why_asked": "単一のAレコードやラウンドロビンは地理を考慮しないため、グローバル配信でユーザーごとに最寄りのリージョンへ案内するにはDNSレベルの出し分けが必要になる点が問われます。", "eg": "カーナビが現在地に応じて最寄りの目的地への最短ルートを案内するようなものです。"}, "gcp-pca-e-q17": {"point": "Cloud SQLでリージョン障害時にも復旧できるようにしたいなら、クロスリージョンのリードレプリカを用意し災害時に昇格させます。", "why_asked": "同一リージョン内のバックアップは、そのリージョン自体が丸ごと落ちたときには役に立ちません。バックアップと別リージョンへの複製の違いを区別できるかが問われます。", "eg": "普段は控えている予備の心臓ペースメーカーが、いざというときに主機能を引き継ぐようなものです。"}, "gcp-pca-e-q18": {"point": "モバイルやWeb向けにリアルタイム同期とオフライン対応を備えたNoSQL文書DBが欲しいならFirestoreを選びます。", "why_asked": "BigtableやBigQueryもNoSQLという括りで混同されやすいですが、Bigtableは大規模時系列データ向け、BigQueryは分析用途であり、クライアントSDKから直接同期する用途には向きません。用途別のDB選定が問われます。", "eg": "家族の共有カレンダーは誰かが更新すると、他の家族のスマホにもすぐ反映されます。それに近い自動同期です。"}, "gcp-pca-e-q19": {"point": "頻繁に読むデータやセッション情報をインメモリで速く扱いたいならMemorystoreを選びます。", "why_asked": "DBの負荷が高いから増強するという発想になりがちですが、読み取りが集中するデータの手前にキャッシュ層を挟むことで、DB本体への負荷とレイテンシを同時に下げられるという設計パターンが問われます。", "eg": "毎回倉庫まで取りに行く代わりに、よく使う調味料は台所の手前の棚に置いておくようなものです。"}, "gcp-pca-e-q20": {"point": "アクセス頻度が下がるデータを消さずコストを最適化したいなら、ライフサイクルでStandardからNearline・Coldline・Archiveへ自動移行させます。", "why_asked": "古いデータは消す、または全部Standardのまま置いておくという二択に陥りがちですが、ストレージクラスを段階的に自動移行させることでコストと保持要件を両立できるという選択肢を知っているかが問われます。", "eg": "季節ごとに着る頻度が落ちた服を、奥のクローゼットへ移していく衣替えのようなものです。"}, "gcp-pca-e-q21": {"point": "決まった2つのリージョンで低レイテンシと地理冗長の両方が欲しいならDual-regionバケットを選びます。", "why_asked": "複数拠点で冗長化したいというだけならmulti-regionと混同しやすいですが、multi-regionは大陸規模の広い括りで特定の2拠点を指定できません。要件が2拠点を明示しているかを読み取れるかが問われます。", "eg": "全国どこかに支店があればよいのではなく、姉妹都市どうしが決まった2都市で助け合う防災協定を結ぶようなものです。"}, "gcp-pca-e-q22": {"point": "日付範囲などで絞り込むクエリが多く性能とコストを改善したいなら、パーティション分割とクラスタリングでスキャン量を減らします。", "why_asked": "BigQueryはスキャンしたデータ量に応じて課金されるため、テーブル設計を最適化しないと不要な列や行まで毎回読み込んでしまい、想定を超える請求額になりやすい実務の落とし穴です。", "eg": "図書館で本をジャンルごとに棚分けしておけば、探している本以外の棚を見なくて済むようなものです。"}, "gcp-pca-e-q23": {"point": "特定の機微列だけを一部ユーザーに見せたくないなら、ポリシータグによる列レベルセキュリティを使います。", "why_asked": "行単位で制御する行レベルセキュリティと混同しやすいですが、これは列を対象にする制御です。またアプリ側でのフィルタだけではDBへの直接アクセスを防げないという抜け穴も問われます。", "eg": "給与明細を上司にだけ見せて、他の同僚には給与欄だけ隠して渡すようなものです。"}, "gcp-pca-e-q24": {"point": "オンプレDBを最小停止でCloud SQLやAlloyDBへ移したいなら、継続的レプリケーションを使うDatabase Migration Serviceを選びます。", "why_asked": "ダンプを一度取って移す方法は手軽に見えますが、その間サービスを止める必要があり、本番DBの移行では許容できないことが多いです。変更データを継続的に写し続けて停止を最小化する方法を知っているかが問われます。", "eg": "店を閉めずに在庫を少しずつ新しい店舗へ運び、最後の一瞬だけ看板を掛け替えるようなものです。"}, "gcp-pca-e-q25": {"point": "回線帯域では現実的な時間で運べない大容量データを移すなら、物理輸送するTransfer Applianceを選びます。", "why_asked": "オンラインで転送すればよいという発想は、数百TB規模になると帯域の制約で現実的な時間に収まらないことがあります。物理輸送の方が結果的に速いというオフライン転送の選択肢を知っているかが問われます。", "eg": "大量の本を少しずつ手で運ぶより、まとめてトラックに積んで運んだ方が速いことがあるのと同じ考え方です。"}, "gcp-pca-e-q26": {"point": "組織全体で外部IP付与などを原則禁止し例外だけ許可したいなら、組織ポリシー制約を組織やフォルダに適用します。", "why_asked": "各プロジェクトへの個別の注意喚起や事後の監査ログ確認では守られる保証がなく、事故が起きてから気づくことになります。階層で継承される予防的なガードレールという設計思想が問われます。", "eg": "各クラスに口頭でルールを伝えるのではなく、校長が定めた校則が全クラスに自動的に適用されるようなものです。"}, "gcp-pca-e-q27": {"point": "APIキーやパスワードをコードに書かず安全に保管・ローテーションしたいならSecret Managerを選びます。", "why_asked": "環境変数に平文で置く方法はコードへの直書きよりましだと誤解されがちですが、環境変数もプロセス情報やログ経由で漏洩することがあります。保管専用サービスに一元化する必要性が問われます。", "eg": "財布を机の上に置きっぱなしにせず、鍵付きの貴重品ロッカーに入れておくようなものです。"}, "gcp-pca-e-q28": {"point": "外部CIからGCPへアクセスさせたいがサービスアカウント鍵を配布したくないなら、Workload Identity Federationを選びます。", "why_asked": "サービスアカウント鍵のJSONファイルは発行後のローテーションや漏洩管理の負担が大きく、CIのシークレットストアから流出する事故が実務で多発します。鍵を発行せず外部IDを信頼して一時的に権限を貸す仕組みを知っているかが問われます。", "eg": "自社の合鍵を配って回るのではなく、提携先の身分証を見せれば一時的に入館できる仕組みにするようなものです。"}, "gcp-pca-e-q29": {"point": "誰がいつデータを読んだかまで記録したいなら、Cloud Audit LogsのData Accessログを有効化します。設定変更の記録(Admin Activity)は既定で有効です。", "why_asked": "監査ログは自動で全部取れているという思い込みが実務の落とし穴で、実は読み取り操作の記録は既定で無効になっています。設定変更の記録と読み取りの記録が別物であるという理解が問われます。", "eg": "誰が本を借りたかの記録は自動で残りますが、誰が館内で立ち読みしたかは別途記録をオンにしないと残らないようなものです。"}, "gcp-pca-e-q30": {"point": "IPや地域・デバイスの状態といった文脈条件でアクセス可否を定義したいなら、Access Context Managerでアクセスレベルを定義します。", "why_asked": "IAMロールは誰に何の権限があるかを決めますが、どんな状況からのアクセスかまでは表現できません。IAPやVPC Service Controlsと組み合わせて文脈条件を効かせるという役割分担の理解が問われます。", "eg": "同じチケットを持っていても、身長制限を満たさないと乗れない遊園地のアトラクションのようなものです。"}, "gcp-pca-e-q31": {"point": "社内向けのプライベート証明書発行局をマネージドで運用したいなら、Certificate Authority Serviceを選びます。", "why_asked": "自前でCAを運用すると可用性・鍵管理・失効処理の負担が大きく、証明書切れによる障害を招きやすいです。マネージドなプライベートCAと、ロードバランサ向けのCertificate Managerとの役割の違いも問われます。", "eg": "自分で印鑑を作っても印鑑証明にはならず、公的な発行元に発行してもらう必要があるのと同じ考え方です。"}, "gcp-pca-e-q32": {"point": "規制でFIPS 140-2 Level 3のハードウェアで鍵を保護したい、かつGCP内で完結させたいならCloud HSMを選びます。", "why_asked": "鍵をGoogleの外部に置くEKMと、GCP内でハードウェア保護するCloud HSMは似た文脈で登場するため混同しやすいです。GCP内で完結という要件を読み取れるかが判断の分かれ目になります。", "eg": "自宅の引き出しではなく、銀行の貸金庫に大事なものを預けるようなものです。"}, "gcp-pca-e-q33": {"point": "コスト・セキュリティ・信頼性の改善を継続的に提案してほしいなら、Recommender(Active Assist)を活用します。", "why_asked": "手動でのコストや権限の棚卸しは実施が属人的になり継続しないため、気づかないうちにアイドル資源や過剰な権限が溜まっていきます。継続的な自動提案の仕組みを知っているかが問われます。", "eg": "人間ドックが自覚症状の出ていない不調を定期的に見つけてくれるように、使っていないリソースをGCPが見つけて教えてくれるようなものです。"}, "gcp-pca-e-q34": {"point": "同じコードでバッチもストリームも書き、オートスケールするフルマネージドな処理基盤が欲しいならDataflowを選びます。", "why_asked": "既存のHadoopやSparkをそのまま移すDataprocと混同しやすいですが、Dataflowは新規でバッチとストリームを統合したコード基盤(Apache Beam)を使う場合に選ぶという使い分けが問われます。", "eg": "録音した音声もリアルタイムの会話も、同じ翻訳エンジンで処理できる自動翻訳機のようなものです。"}, "gcp-pca-e-q35": {"point": "既存のHadoopやSparkジョブをほぼそのままGCPへ移したいならDataprocを選びます。", "why_asked": "新規でストリーム処理を統合したいDataflowと役割が近く見えますが、Dataprocは既存資産をそのまま移すリフト＆シフトの文脈で選ぶという判断基準が問われます。", "eg": "使い慣れた家電を買い替えずに、そのまま新居のコンセントに挿して使い続けるようなものです。"}, "gcp-pca-e-q36": {"point": "繰り返し失敗するメッセージを隔離して本流を止めたくないなら、デッドレタートピックを設定します。", "why_asked": "失敗したメッセージを放置すると再配信が繰り返され、サブスクリプション全体の処理が滞留します。失敗の隔離という設計判断が、順序保証やexactly-onceといった他のPub/Sub機能と混同されやすいので区別が問われます。", "eg": "工場のラインで何度も検査に落ちる部品を、本流のラインから外して別に保管しておくようなものです。"}, "gcp-pca-e-q37": {"point": "コードを書かずGUIでETLを構築・運用したい、非エンジニアも触るならCloud Data Fusionを選びます。", "why_asked": "DataflowやDataprocはコードベースの処理基盤なので、非エンジニアが扱う前提の要件では選択を誤りやすいです。誰が構築・運用するかという運用面の要件がサービス選定を左右する点が問われます。", "eg": "文字の説明書ではなく、絵カードを組み合わせて手順がわかる子供向け調理キットのようなものです。"}, "gcp-pca-e-q38": {"point": "MLのデータ準備から学習・パイプライン・デプロイまで一貫したプラットフォームで扱いたいならVertex AIを選びます。", "why_asked": "BigQuery MLは手軽にSQLでモデルを作れますが、パイプライン管理やモデルレジストリ、デプロイまで含めた本格的なMLOpsを一つのプラットフォームで統合する場合はVertex AIを選ぶという使い分けが問われます。", "eg": "検査から治療まで一つの病院で完結するワンストップの総合病院のようなものです。"}, "gcp-pca-e-q39": {"point": "BigQueryのデータセットをコピーせず組織内外と安全に共有・交換したいならAnalytics Hubを選びます。", "why_asked": "CSVエクスポートやバケットの公開はコピーが増えて鮮度やガバナンスが崩れやすいです。元データを複製せず貸し出す形で共有するという発想の転換が問われます。", "eg": "本そのものをコピーして配るのではなく、必要なときに借りられるようにする図書館の相互貸借制度のようなものです。"}, "gcp-pca-e-q40": {"point": "信頼性を定量管理し新機能投入と安定性のバランスを取りたいなら、SLIを計測しSLOを定義してエラーバジェットで意思決定します。", "why_asked": "稼働率は高ければ高いほど良いという直感に反して、100%稼働を目指すとコストが跳ね上がり非現実的になります。許容される不調の量を予算として捉え、開発速度とのトレードオフを定量的に判断するというSREの基本発想が問われます。", "eg": "毎月使ってよい予算の範囲内で家計をやりくりするように、許容される失敗の残り分を見ながら新しい挑戦をするかどうかを決めるようなものです。"}, "gcp-pca-e-q41": {"point": "外部から見たエンドポイントの死活やレイテンシを定期監視し、閾値を超えたら通知したいなら、Cloud Monitoringの稼働時間チェックとアラートポリシーを組み合わせます。", "why_asked": "ユーザーからの苦情を待つ受動的な検知では障害の発見が遅れ、影響範囲が広がってから気づくことになります。外形監視で能動的に検知する設計が信頼性運用の基本として問われます。", "eg": "自覚症状が出る前に定期検診で不調を見つけるように、店の扉が実際に開くかを外から定期的に確認する見回りのようなものです。"}, "gcp-pca-e-q42": {"point": "監査や長期分析のため各種ログをBigQueryやGCSへ集約したいなら、ログシンクでエクスポートします。", "why_asked": "Cloud Loggingのコンソールで都度見るだけでは長期保管や横断分析に向かず、保持期間の制約もあります。用途別に行き先を分けてルーティングするという設計が実務で問われます。", "eg": "すぐ使う書類・倉庫保管の書類・外部提出用の書類を分けて保管する社内の書類保管規定のようなものです。"}, "gcp-pca-e-q43": {"point": "レイテンシ悪化の原因を切り分けたいなら、遅い処理はCloud Trace、資源消費はProfiler、頻発エラーはError Reportingと役割ごとに使い分けます。", "why_asked": "分散システムでは処理が複数のサービスをまたぐため、勘やprintデバッグでは原因箇所を特定できません。目的が異なる複数のオブザーバビリティツールを組み合わせて切り分けるという実務の型が問われます。", "eg": "車の不調の原因を、エンジン音・燃費・警告灯という別々の計器で確認して絞り込む故障診断のようなものです。"}, "gcp-pca-e-q44": {"point": "RTOとRPOをほぼゼロにしたい、コストは許容できるという要件なら、マルチリージョンのアクティブ/アクティブ構成を選びます。", "why_asked": "DR構成にはコストと復旧速度のトレードオフの階層があり、要件文のコストは許容やほぼゼロという言葉を読み取れないと、過剰または不足な構成を選んでしまいます。段階的なDR戦略の中でどこに位置するかの理解が問われます。", "eg": "発電所が予備電源を普段から稼働させておき、瞬時に切り替えられるようにしておくようなものです。"}, "gcp-pca-e-q45": {"point": "devからstagingそしてprodへの承認とカナリア付き段階昇格をマネージドに運用したいなら、Cloud Deployを選びます。", "why_asked": "手動でのkubectl applyは属人的で監査証跡が残らず、本番昇格時の承認プロセスも保証されません。継続的デリバリのパイプラインを標準化するという実務要件が問われます。", "eg": "通し稽古を経てプレビュー公演を行い、そのうえで本番に臨む演劇のように、段階を踏んで確認しながら進めるようなものです。"}, "gcp-pca-e-q46": {"point": "インフラ構成をコードで宣言し再現可能・レビュー可能・バージョン管理したい、マルチクラウドも視野に入れるならTerraformを選びます。", "why_asked": "コンソールでの手作業は再現性がなく、環境ごとの設定のずれ(ドリフト)が発生しやすいです。宣言的なIaCでインフラをコードとして管理するという実務標準が問われます。", "eg": "組み立て家具の説明書のように、図面通りに組み立てれば誰が作っても同じ物ができるようなものです。"}, "gcp-pca-e-q47": {"point": "短期は変更を最小にして素早く移し、後で段階的に改善したいなら、リホスト(lift & shift)を起点にします。", "why_asked": "移行プロジェクトでは最初から理想形にリファクタしたい誘惑に駆られがちですが、期限が短い案件では工数とリスクが跳ね上がります。まず動かしてから改善する段階的アプローチが実務で問われます。", "eg": "リフォームを終えてから住み始めるのではなく、古い家にまず住み始めて、住みながら少しずつ手を入れていくようなものです。"}, "gcp-pca-e-q48": {"point": "データ持ち出しのリスクを下げるには、境界の外へ持ち出せなくする仕組みと、外部への権限付与そのものを防ぐ仕組みを組み合わせます。", "why_asked": "対策を1つだけ導入して満足しがちですが、境界での遮断と外部への権限付与の禁止は防ぐ経路が異なります。両方揃って初めて多層防御になるという理解が問われます。", "eg": "貴重書を館外に持ち出させない規則と、そもそも外部の人に貸出カードを発行しない規則を、両方同時に敷く図書館のようなものです。"}, "gcp-pca-e-q49": {"point": "境界外への持ち出し防止、アクセス条件の限定、鍵の自社統制、データアクセスの監査という4要件を満たすには、複数の仕組みを重ねる多層防御で構成します。", "why_asked": "単一の仕組みでは1つの要件しか満たせないため、規制の厳しい業界では複数のガードレールを重ねる設計力が問われます。どの要件がどの仕組みに対応するかを正確に紐づけられるかがカギです。", "eg": "展示ケースと入場条件と警備員が持つ鍵、そして来場者記録を組み合わせて貴重品を守る美術館の展示のようなものです。"}, "gcp-pca-e-q50": {"point": "DBは止めずに移し、アプリはまず素早く移設し、その後で段階的にコンテナ化し、リリースは段階昇格で安全にという要件には、この順序で組み合わせて設計します。", "why_asked": "複数の移行要素が絡む設計問題では、個々の技術を知っているだけでなく、それらを正しい順序に組み立てられるかという統合力が問われます。", "eg": "患者を移しながら今の設備で診療を続け、落ち着いてから新しい機器を順次導入し、正式な開院は段階的に案内する病院の新病棟移転のようなものです。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-e')
  AND q.explanation_data IS NOT NULL;

-- gcp-pca-f
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-f-q1": {"point": "無トラフィック時に完全に0まで止めてコストを切り詰めたいなら、Standardのゼロスケールを選ぶ。", "why_asked": "名前が似ているStandardとFlexibleを混同しやすく、実務でも『0まで止まると思ったら課金され続けた』という取り違えが起きやすいため、スケール特性の違いは頻出。", "eg": "コンビニが深夜に完全にシャッターを閉められるか、最低1人は店番を置かなければならないかの違いのようなもの。"}, "gcp-pca-f-q2": {"point": "新バージョンをいきなり全量に晒さず少しずつ試したいなら、リビジョン間のトラフィック分割で割合を指定する。", "why_asked": "デプロイ方式(全量切替・カナリア・ブルーグリーン)の使い分けは設計問題で頻出。段階移行を『別サービスの新規作成』と混同すると、URLが変わるという別の問題を招く。", "eg": "新しいレシピを店の全メニューに一気に出すのではなく、まず一部のお客さんにだけ試食してもらってから広げるのに近い。"}, "gcp-pca-f-q3": {"point": "大量のバッチジョブをキューイング・スケジューリングまで含めてマネージドに回したいなら、Cloud Batch。", "why_asked": "自前でVMを並べて分散処理を組もうとする誤答に引っかかりやすく、『マネージドで完結する』のがCloud Batchの価値だと理解しているかが問われる。", "eg": "大量の洗濯物を1人で手洗いするのではなく、コインランドリーの多数の洗濯機に自動で割り振って一気に片付けるようなもの。"}, "gcp-pca-f-q4": {"point": "IOPSとスループットを要件に合わせて個別に調整したい高性能ディスクなら、Hyperdisk。", "why_asked": "ローカルSSDの速さと引き換えの揮発性、pd-standardの性能限界との違いが分かっていないと、性能要件とデータ永続性要件を両立できる選択肢を見誤る。", "eg": "水道の「量」と「勢い」を別々のつまみで調整できる特別な蛇口のようなもの。"}, "gcp-pca-f-q5": {"point": "起動時の改ざん(ルートキット等)を検知・防止したいなら、Shielded VM。", "why_asked": "『セキュアなVM』という括りでConfidential VMと混同されやすいが、Shielded VMは起動の完全性、Confidential VMは使用中データの暗号化と、守る対象が違うため要件文の読み分けが試される。", "eg": "家に入るときに鍵と本人確認をしっかりするのがShielded VM、家の中で話す内容を誰にも聞かれないよう防音するのがConfidential VMのようなもの。"}, "gcp-pca-f-q6": {"point": "決まった時間帯だけVMを動かしたいなら、インスタンススケジュール(リソースポリシー)で自動起動/停止を設定する。", "why_asked": "手動運用は『止め忘れ』という運用事故が起きやすく、コスト最適化の実務でまず手を付けるべき定番施策として問われる。", "eg": "毎晩決まった時間に照明が消えて、朝また点くタイマー付きの家電のようなもの。"}, "gcp-pca-f-q7": {"point": "検証環境は速さ重視、本番は安定重視、と環境ごとにアップグレード方針を変えたいなら、リリースチャンネルを選択する。", "why_asked": "『アップグレードは全部手動が安全』という直感に流されがちだが、実際は手動運用が更新漏れやセキュリティパッチの遅延を招くため、チャンネル選択の理解が問われる。", "eg": "新商品をすぐ試したい客と、枯れて安定してから使いたい客とで、案内するコースを分けるようなもの。"}, "gcp-pca-f-q8": {"point": "世界中のユーザー向けにHTTPを単一IPで公開し、パスやホストで賢く振り分け、Cloud Armorも使いたいなら、グローバル外部アプリケーションLB(L7)。", "why_asked": "L4とL7の違い(URLベースの振り分けができるかどうか)や、内部/外部LBの取り違えは頻出の混同ポイントで、要件文のキーワード(HTTP、単一IP、パスベース)を正しく拾えるかが試される。", "eg": "全国共通の代表番号にかければ、内容を聞いて担当部署へ自動で繋いでくれる総合案内窓口のようなもの。"}, "gcp-pca-f-q9": {"point": "オンプレ〜GCP間のVPNに99.99%のSLAを求めるなら、HA VPN(冗長インターフェース＋2トンネル)。", "why_asked": "Classic VPNとの違い(冗長構成の有無)を理解していないと、SLA要件を満たせない設計を選んでしまうため、可用性要件からの逆算力が問われる。", "eg": "橋を1本しか架けていないと通行止めで孤立するが、2本架けておけば片方が壊れても渡れるようなもの。"}, "gcp-pca-f-q10": {"point": "Cloud Run/Functionsなどサーバーレスから、VPC内のプライベートIPだけのリソースへ到達させたいなら、Serverless VPC Accessコネクタ。", "why_asked": "サーバーレスは基本的にVPCの外にいるという前提を理解していないと、Cloud NAT(外向き専用)と取り違えて、内部到達の要件を満たせない設計を選んでしまう。", "eg": "別棟にあるサーバーレスの部署と、本館の社内システムをつなぐ専用の連絡通路を架けるようなもの。"}, "gcp-pca-f-q11": {"point": "誰が誰と、いつ、どれだけ通信したかをサンプリング記録してフォレンジックや分析に使いたいなら、VPCフローログ。", "why_asked": "ファイアウォールルールロギング(許可/拒否の記録)と目的が違うため混同しやすく、『通信の中身の傾向を知りたいのか、ルールの適用結果を知りたいのか』を要件文から読み分ける力が試される。", "eg": "誰が何時にどれだけ電話したかを記録する通話履歴のようなもの。あとから調べ直せる。"}, "gcp-pca-f-q12": {"point": "既知の攻撃シグネチャや不審な侵入を検知するマネージドな仕組みが欲しいなら、Cloud IDS。", "why_asked": "Cloud Armor(Webアプリ層の防御)やVPCフローログ(可視化)と役割が重なって見えるが、『既知の脅威パターンを検知する』という侵入検知(IDS)特有の機能を理解しているかが問われる。", "eg": "防犯カメラの映像を専門家が常時チェックして、既知の手口を見つけたら通報してくれる警備サービスのようなもの。"}, "gcp-pca-f-q13": {"point": "マイクロサービス間の通信にmTLS・トラフィック制御・観測性を、アプリの改修を最小限にして入れたいなら、Cloud Service Mesh。", "why_asked": "各サービスに自前でTLSを実装する案は『技術的には可能』に見えて保守コストが破綻しやすく、インフラ層で横断的に解決する発想が問われる。", "eg": "各部署の社員に通訳や警備を個別に雇わせるのではなく、建物全体に共通の通訳・警備係(サイドカー)を配置するようなもの。"}, "gcp-pca-f-q14": {"point": "『つながらない・遅い』を経路や設定から体系的に診断したいなら、Network Intelligence Center。", "why_asked": "実務では手動pingや当て推量での設定変更に頼りがちだが、それでは再現性・網羅性に欠けるため、マネージドな診断ツールの存在と用途が問われる。", "eg": "電気の配線図と通電チェッカーを使って、どこで断線しているかを体系的に突き止めるようなもの。"}, "gcp-pca-f-q15": {"point": "インターネットに出さず、VPC内だけで通じる名前解決を用意したいなら、Cloud DNSのプライベートゾーン。", "why_asked": "パブリックゾーンとの違い(公開範囲)を理解していないと、内部名を意図せず外部に晒す設計になりかねないため、公開/非公開の切り分けが問われる。", "eg": "社内だけで通じる内線番号簿のようなもの。外部からは引けない。"}, "gcp-pca-f-q16": {"point": "数時間前など特定の時点まで巻き戻して復旧したいなら、ポイントインタイムリカバリ(PITR)。", "why_asked": "日次バックアップだけでは『前日の状態』にしか戻せず、事故直前の細かい時点には戻せないため、バックアップの粒度の違いが問われる。", "eg": "動画を事故の1コマ前まで巻き戻して、そこから再生し直すようなもの。"}, "gcp-pca-f-q17": {"point": "DBログインもパスワードを別途配らず、IAMの資格情報で一元管理したいなら、IAMデータベース認証。", "why_asked": "共有パスワード配布は漏洩・監査困難という実務上の落とし穴があり、ID管理を一箇所に集約する設計思想が問われる。", "eg": "部屋ごとの合鍵を配るのではなく、社員証一枚でどこにでも入れるようにするようなもの。"}, "gcp-pca-f-q18": {"point": "ゾーン障害でもデータを失わずに別ゾーンで復旧したいステートフルVMなら、リージョンPersistent Disk(2ゾーン同期レプリケーション)。", "why_asked": "ゾーンPDやローカルSSDは高性能に見えて単一ゾーン依存または揮発性という弱点があり、可用性要件を満たす冗長化のレベルを正しく選べるかが問われる。", "eg": "大事な書類を2つの部屋に同時に保管しておき、片方が浸水しても無事なもう片方が残るようなもの。"}, "gcp-pca-f-q19": {"point": "バックアップと復旧を個別スクリプトでなく一元的にポリシー管理したいなら、Backup and DR Service。", "why_asked": "各チームがcronや手動スナップショットでバラバラに運用すると統制が効かず復旧漏れが起きるため、中央集権的な管理の必要性が問われる。", "eg": "各部署がバラバラに控えを取るのをやめ、全社共通の保管ルールと管理者を置くようなもの。"}, "gcp-pca-f-q20": {"point": "GCS上のデータをBigQueryにロードせずその場でクエリし、列/行レベルの制御も効かせたいなら、BigLakeテーブル。", "why_asked": "『分析するなら全部ロードすべき』という発想に流れがちだが、ロードにはコピーや取込のコストが伴うため、ロードせず安全にクエリするアプローチの理解が問われる。", "eg": "倉庫の在庫をいちいち運び出さず、その場で棚卸しするようなもの。"}, "gcp-pca-f-q21": {"point": "Bigtableで複数クラスタ間の読み書きの向き先(一貫性重視か可用性重視か)を制御したいなら、アプリプロファイル。", "why_asked": "行キー設計(分散のしかた)とルーティング設定(どのクラスタに向けるか)は別の観点であり、混同すると『そもそも制御できない』という誤解に陥りやすい。", "eg": "問い合わせ先を『本店だけに聞く』か『一番近い店ならどこでもいい』かで使い分ける設定のようなもの。"}, "gcp-pca-f-q22": {"point": "SQLも強整合も不要で、超高スループットの時系列/IoTデータをさばきたいならBigtable。SQLと強整合が要るならSpannerを選ぶ。", "why_asked": "『分散データベース』という括りでBigtableとSpannerを混同しやすく、要件文の『SQL不要』『数百万QPS』というキーワードから正しい方を選べるかが試される。", "eg": "伝票をものすごい速さでひたすら積み上げる倉庫がBigtable、1件ずつ厳密に整合性を取って記帳する台帳がSpannerのようなもの。"}, "gcp-pca-f-q23": {"point": "ディスクの定期スナップショットを自動化し、別リージョンにも保存してDRに備えたいなら、スナップショットスケジュール(リソースポリシー)。", "why_asked": "手動運用は取り忘れが起き、複製コピーは非効率なため、増分バックアップの自動化と地域分散を両立する仕組みの理解が問われる。", "eg": "定期的に書類のコピーを取り、遠くの倉庫にも預けておくようなもの。"}, "gcp-pca-f-q24": {"point": "既存の外部IdPのIDでそのままGCPにSSOログインさせ、別パスワードを作りたくないなら、Workforce Identity Federation。", "why_asked": "『新しくGoogleパスワードを発行すればいい』という安易な発想は二重管理という運用負債を生むため、ID連携によって管理を一元化する設計が問われる。", "eg": "提携先の社員証をそのまま使って自社ビルにも入れるようにし、新しい証は発行しないようにするようなもの。"}, "gcp-pca-f-q25": {"point": "実際の使用状況に基づいて過剰な権限を洗い出し、最小権限へ削減したいなら、IAM Recommender(Policy Intelligence)。", "why_asked": "手動での棚卸しは網羅性に欠け、逆にEditorへの統一は最小権限の原則に反するため、データに基づく自動推奨の仕組みが問われる。", "eg": "誰も使っていない合鍵を洗い出して、回収を提案してくれるようなもの。"}, "gcp-pca-f-q26": {"point": "元データの分析可能性を保ちつつ、氏名やカード番号などの機微情報だけをマスキング・トークン化したいなら、Sensitive Data Protection(DLP)のde-identification。", "why_asked": "列を丸ごと削除すると分析に必要な構造まで失われるため、『隠しつつ使える形を保つ』という匿名化技法特有の価値が問われる。", "eg": "氏名を伏字や別のIDに置き換えて、誰のデータか分からないようにしつつ集計はできるようにするようなもの。"}, "gcp-pca-f-q27": {"point": "Googleサポート担当がデータへアクセスする際に事前承認を必須にし、履歴も可視化したいなら、Access Approval＋Access Transparency。", "why_asked": "監査ログを事後に見るだけでは『事前に止める』統制にならないため、可視化(Transparency)と承認(Approval)がセットで必要という理解が問われる。", "eg": "業者が入室するたびに記録を残すだけでなく、入る前に必ず許可を取らせる運用のようなもの。"}, "gcp-pca-f-q28": {"point": "IAM条件や組織ポリシーの適用対象を分類・強制したいなら、課金集計用のラベルではなく「タグ」を使う。", "why_asked": "タグとラベルは見た目が似たキー/バリューの仕組みだが、ポリシー強制に使えるかどうかという役割が全く違うため、実務でも取り違えやすい定番の混同ポイント。", "eg": "入館できる区画を決める権限区分の札(タグ)と、経費精算に使う費目の札(ラベル)は、同じ「札」でも役割が違うようなもの。"}, "gcp-pca-f-q29": {"point": "管理者でもうっかり消せないよう重要プロジェクトの誤削除を防ぎたいなら、リーエン(lien)を設定する。", "why_asked": "『オーナー権限を減らせば安全』と考えがちだが、権限を持つ人自身の誤操作は防げないため、削除操作そのものにロックをかける仕組みの理解が問われる。", "eg": "重要な書類の入った引き出しに、外さない限り開かない鍵をかけておくようなもの。"}, "gcp-pca-f-q30": {"point": "自社アプリの顧客(エンドユーザー)向けにサインイン・MFA・SNSログインを組み込みたいなら、Identity Platform。社員のID管理はCloud Identity。", "why_asked": "『ID管理』という括りでCloud Identityと混同しやすいが、対象が社員(社内)か顧客(社外)かで使うサービスが全く違うため、B2Cという要件文のキーワードを読み取れるかが試される。", "eg": "会員サイトの会員ログイン機能(顧客向け)と、社員証の発行システム(社員向け)は別物というようなもの。"}, "gcp-pca-f-q31": {"point": "事前定義の制約に無い自社固有のルールを強制したいなら、カスタム組織ポリシー制約を定義する。", "why_asked": "手動レビューは抜けが出やすく予防的でないため、『既製の制約に無いルールは強制できない』という思い込みを崩し、自分で条件を定義できることが問われる。", "eg": "既製のルールブックに無い社内独自の規則を、自分で条文化して全社に強制するようなもの。"}, "gcp-pca-f-q32": {"point": "BigQueryだけで完結する定期集計を、外部のオーケストレータなしで回したいなら、スケジュールドクエリ。", "why_asked": "複雑な依存関係のあるパイプラインならComposerが適するが、単純な定期実行にComposerを持ち出すのは過剰であり、要件の規模に見合った選択が問われる。", "eg": "目覚まし時計をセットしておけば、毎朝自動で決まった作業が走るようなもの。"}, "gcp-pca-f-q33": {"point": "BigQuery上のSQL変換(ELT)を依存関係・バージョン管理・テスト付きで開発運用したいなら、Dataform。", "why_asked": "Composerは汎用オーケストレーションで守備範囲が広い分、SQLのELTだけを軽量に管理したい要件には過剰であり、目的に応じた道具選びが問われる。", "eg": "SQLをその場しのぎで書くのではなく、アプリ開発のようにバージョン管理とテストを付けて運用するようなもの。"}, "gcp-pca-f-q34": {"point": "Pub/Subに流れるメッセージの構造を契約として強制し、不正な形式を送信の時点で弾きたいなら、Pub/Subスキーマ(Avro/Protobuf)。", "why_asked": "受信側だけでバリデーションする案は『事後の防御』に過ぎず不正データの流入自体は防げないため、契約を送信元で強制する発想が問われる。", "eg": "必須欄が埋まっていない申込用紙は、その場で受け付けてもらえない窓口のようなもの。"}, "gcp-pca-f-q35": {"point": "処理済みのメッセージを過去の時点まで巻き戻して再配信したいなら、メッセージリテンションを設定し、seekで巻き戻す。", "why_asked": "再publishでは元データを正確に再現するのが難しいため、保持期間内であればそのまま巻き戻せるPub/Sub固有の機能を理解しているかが問われる。", "eg": "録画を巻き戻して、その時点からもう一度再生し直すようなもの。"}, "gcp-pca-f-q36": {"point": "本番モデルの予測精度が入力データの分布ずれで劣化していないか監視したいなら、Vertex AI Model Monitoring(スキュー/ドリフト検知)。", "why_asked": "『毎日再学習すれば安心』という発想はコストが過大になるため、劣化を検知してから対応するという監視ベースの設計思想が問われる。", "eg": "健康診断の基準値から外れ始めたら通知が来る仕組みのようなもの。"}, "gcp-pca-f-q37": {"point": "データを動かさず、SQLだけでモデルの学習・予測まで完結させたいなら、BigQuery ML。", "why_asked": "MLOps全体の統合管理が必要ならVertex AIが適するが、『データベースの中で完結する軽量なML』という要件にはBigQuery MLが最適で、その使い分けが問われる。", "eg": "分析している机の上で、データを持ち出さずにそのまま予測モデルも作ってしまうようなもの。"}, "gcp-pca-f-q38": {"point": "多数のGKEクラスタの設定をGitで一元管理して同期し、ポリシー違反を防ぎたいなら、Config Sync＋Policy Controller。", "why_asked": "クラスタが増えるほど手動kubectl運用は破綻しやすく、Gitを正とするGitOpsとポリシー強制をセットで理解しているかが問われる。", "eg": "全店舗のマニュアルを本部で一括更新し、規定違反の運用は自動でブロックするようなもの。"}, "gcp-pca-f-q39": {"point": "ログ中の特定パターンの出現回数を指標化し、しきい値超過で通知したいなら、ログベースの指標＋アラートポリシー。", "why_asked": "ログを目視で数える運用は人手で追い切れず見逃しが起きるため、指標化して自動監視する設計が実務でも定番として問われる。", "eg": "特定の苦情ワードが何回出たかを自動で数え、急増したら警報を鳴らすようなもの。"}, "gcp-pca-f-q40": {"point": "複数リージョンのGKEクラスタにまたがってトラフィックを振り分け、リージョン障害時も継続したいなら、マルチクラスタIngress/Gateway。", "why_asked": "単一クラスタやDNSラウンドロビンは地域冗長や障害検知の面で弱く、フリート単位でのグローバルなルーティング設計の理解が問われる。", "eg": "全国の店舗網に共通の受付を置き、1店が休業していても他の店へ自動で案内するようなもの。"}, "gcp-pca-f-q41": {"point": "SLOのエラーバジェットの消費が急加速していることに早く気づきたいなら、バーンレートアラート。", "why_asked": "月末にまとめて確認する運用では枯渇に気づいた時には手遅れになりやすく、消費『速度』を見て早期に警報を出す発想が問われる。", "eg": "おこづかいの減りが急に速くなったら、使い切る前に警告が来るようなもの。"}, "gcp-pca-f-q42": {"point": "ヘルスチェックに失敗したインスタンスを自動で作り直して正常状態を保ちたいなら、オートヒーリング。", "why_asked": "手動での再作成は対応が遅れて可用性を損なうため、ヘルスチェックと連動した自動復旧の仕組みが問われる。", "eg": "調子の悪い機械を自動で新品に入れ替え、ライン全体を止めないようにするようなもの。"}, "gcp-pca-f-q43": {"point": "大規模移行の前に既存資産の棚卸し・依存関係・TCOを見積もって計画を立てたいなら、Migration Center。", "why_asked": "勘や見切り発車での移行は手戻りやコスト超過を招きやすく、データに基づくアセスメントを最初に行う重要性が問われる。", "eg": "引っ越し前に荷物の量と動線を調べ、見積もりを取ってから計画を立てるようなもの。"}, "gcp-pca-f-q44": {"point": "特定のマシンタイプ・リージョンで3年など長期にわたり安定して使うなら、リソースベースの確約利用割引(CUD)が最大の割引になる。", "why_asked": "構成が変動する場合は柔軟(支出ベース)CUDの方が有利なため、ワークロードの安定性(固定か変動か)から適切な割引種別を選べるかが問われる。", "eg": "通う店が決まっているなら、その店専用の年間パスを買うのが一番お得というようなもの。"}, "gcp-pca-f-q45": {"point": "特に確約や設定をしなくても、月の大半を稼働させているだけで自動的に安くなるのは、継続利用割引(SUD)。", "why_asked": "確約利用割引(CUD)は事前のコミットが必要なのに対し、SUDはコミット不要で自動適用されるという違いが、コスト最適化の基本として問われる。", "eg": "長く営業しているだけで自動的にポイントが付くお店のようなもの。"}, "gcp-pca-f-q46": {"point": "新規組織立ち上げ時にIAM・ネットワーク・ログ・課金・セキュリティの初期構成を一気にベストプラクティスで整えたいなら、ランディングゾーン/セキュリティ基盤ブループリント(IaCテンプレート)を使う。", "why_asked": "手探りで1つずつ作ると抜けやブレが生じ、後から直すのは負債化しやすいため、最初にテンプレートで土台を整える重要性が問われる。", "eg": "家を建てる前に、配線・水道・防犯の標準設計図をもとに基礎工事を一気に済ませるようなもの。"}, "gcp-pca-f-q47": {"point": "変動の大きいワークロードでは、中断に強い処理はSpot VM、安定した定常分はリソースベースCUDと、性質ごとに割引手段を使い分けるのが正解。", "why_asked": "全部オンデマンドや常時起動といった『とにかく単純にしておく』選択は割引機会と効率を両方逃すため、ワークロードの性質に応じた組み合わせの判断力が問われる。", "eg": "普段使う分は年間パス(CUD)で、たまの臨時需要はバーゲン品(Spot)で賄うようなもの。"}, "gcp-pca-f-q48": {"point": "GKEのセキュリティ強化では、Podに SA鍵を配らず権限を渡すWorkload Identityと、承認済みイメージのみ許可するBinary Authorizationを組み合わせるのが正解。", "why_asked": "特権コンテナや外部IPの一律付与は攻撃対象を広げる典型的な悪手であり、『鍵を持たせない』『検証済みのものしか動かさない』という最小権限の原則を実装レベルで理解しているかが問われる。", "eg": "合鍵を配らず社員証で本人確認する仕組み(Workload Identity)と、検査済みの荷物だけ搬入を許可する仕組み(Binary Authorization)を組み合わせるようなもの。"}, "gcp-pca-f-q49": {"point": "オンプレ・GCP・他クラウドにまたがる多数のKubernetesを一貫した構成・共通のデプロイ体験・mTLSと観測性で運用したいなら、GKE Enterprise(Anthos)によるフリート管理＋Config Sync/Policy Controller＋Cloud Service Meshを組み合わせる。", "why_asked": "個別運用は環境ごとに手作業で揃えることになり一貫性を保てず、逆に1つのクラウドへの強制集約は制約やコストが過大になるため、複数要件を同時に満たす統合アプローチを選べるかが問われる。", "eg": "国内外の店舗を、共通の本部システムで一括管理して品質を揃えるようなもの。"}, "gcp-pca-f-q50": {"point": "急増するイベントをサーバーレスで取り込み、変換し、SQLで分析し、BIで可視化したいなら、Pub/Sub→Dataflow→BigQuery→Lookerの定番構成を選ぶ。", "why_asked": "Cloud SQLへの直接書き込みや手集計は高頻度のイベントに耐えられずボトルネックになりやすいため、取り込みから可視化までを一貫してサーバーレスで組む定石パターンの理解が問われる。", "eg": "原料受け入れから加工、倉庫での分析、店頭での表示までが一本の流れでつながっている工場のようなもの。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-f')
  AND q.explanation_data IS NOT NULL;

-- gcp-pca-g
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pca-g-q51": {"point": "オンプレとGCPをVPNでつなぐなら、GCP側のVPCにはオンプレと重複しないCIDRを割り当てるのが大前提。", "why_asked": "ハイブリッド接続の設計問題はPCA試験の定番で、通信をどう暗号化するかより先に、IPアドレス設計の初歩を守れているかが問われる。ここを誤ると経路全体が破綻するため出題頻度が高い。", "kid": "オンプレとGCPの住所（IPアドレスの範囲）が被っていると、配達員であるルーターがどちらの家に荷物を届ければよいか判断できなくなる。だから最初から住所を被らせないことが設計の土台になる。", "eg": "同じ町名・同じ番地の家が2つの街に存在したら、郵便配達員はどちらに届けるべきか判断できない。VPCのCIDR設計は、街ごとに重複しない住所を割り振る都市計画のようなもの。"}, "gcp-pca-g-q52": {"point": "マニフェストが既に手元にあり最短で動かしたいなら、gcloudでクラスタを作ってkubectl applyするのが一番シンプルで速い。", "why_asked": "試験は「最新のツールを使う」ではなく「今ある物を最小工程で動かす」判断力を問う。IaCやCI/CDパイプラインの一般論に飛びつくと工程が増えてしまう、という典型的なひっかけ問題。", "kid": "家具（マニフェスト）はもう出来上がっているので、あとは家（クラスタ）を建てて運び込むだけでよい。余計な引っ越しコンサル（Terraformやパイプライン構築）を挟むと、その分だけ工程が増えるだけ。", "eg": "料理のレシピ（マニフェスト）はもう手元にあるのに、キッチン（クラスタ）がまだ無い状態。まずキッチンを作って、そのままレシピ通り作り始めるのが一番早く、わざわざ厨房設計コンサルを呼ぶ必要はない。"}, "gcp-pca-g-q53": {"point": "新規インスタンスを起動直後から即戦力にしたいなら、依存パッケージを事前に焼き込んだカスタムイメージを使うのが決め手。", "why_asked": "MIGのオートスケーリングでは、新規インスタンスの起動待ち時間の長さがスケール追従の速さをそのまま左右する。「起動してから準備する」方式と「準備してから起動する」方式の違いを理解しているかを問う。", "kid": "毎回工具箱を組み立てながら作業を始めるのではなく、あらかじめ工具を全部詰めた箱を用意しておけば、箱を開けた瞬間から作業に入れる。", "eg": "引っ越し先で毎回家具を一から組み立てるのと、あらかじめ組み立て済みの家具ごとトラックで運び込むのとの違い。後者なら到着した瞬間から暮らし始められる。"}, "gcp-pca-g-q54": {"point": "通信の許可・拒否を階層ごとに制御したいなら、経路（ルーティング）ではなくネットワークタグを条件にしたファイアウォールルールが決め手。", "why_asked": "経路制御とアクセス制御を混同していないかを突く定番パターン。VMの台数が増えても運用負荷を増やさない設計になっているかも同時に見られている。", "kid": "経路を変えても「通っていいか悪いか」の判定はできない。誰が誰に話しかけていいかのルールブックを作るのがファイアウォールの役目で、送信元と宛先の組み合わせをタグで指定すればそのルールブックが作れる。", "eg": "オフィスビルで「1階から3階へは直接入れないが、2階を経由すればよい」というルールは、廊下の作り方ではなく警備員の入館証チェックで実現する。ネットワークタグは、その入館証の色分けにあたる。"}, "gcp-pca-g-q55": {"point": "Podが再作成されても同じホスト名でいてほしいなら、StatefulSetが決め手。", "why_asked": "Kubernetesのワークロード種別を要件から正しく選び分けられるかは頻出テーマ。「状態や識別名を保ちたいワークロードかどうか」の見極めが問われる。", "kid": "引っ越すたびに表札の名前が変わる家（Deployment配下のPod）と、引っ越しても同じ表札を掲げ続ける家（StatefulSet配下のPod）がある。外部から常に同じ名前で訪ねたいなら後者を選ぶ。", "eg": "社員が異動しても「営業部長」という肩書きの名刺は変わらない役職名のようなもの。中の人（Pod本体）は入れ替わっても、呼び名（ホスト名）だけは固定される。"}, "gcp-pca-g-q56": {"point": "Key（識別子）が既にわかっているなら、クエリで探すのではなくバッチgetで直接引くのが一番速い。", "why_asked": "「探す（クエリ）」と「引く（Key指定）」のコスト差を理解しているかを問う。既知のIDに対して不要な検索コストをかけていないかが設計の分かれ目になる。", "kid": "本のタイトルしか分からず本棚を端から探すのがクエリ。既に背表紙の番号（Key）が分かっているなら、その番号の場所に直接手を伸ばせばよい。", "eg": "図書館で「あの本、何巻だっけ」と探し回るのと、「3階の書架番号A-12」と分かっていて直接そこへ向かうのとの違い。番号が分かっているなら探さず直接取りに行くほうが速い。"}, "gcp-pca-g-q57": {"point": "顧客管理の鍵（CSEK）そのものをリクエストに渡したいなら、gsutilの設定ファイルに鍵を書くのが決め手。Cloud KMSの鍵を指定する方式はCMEKであり別物。", "why_asked": "CSEKとCMEKという似た略語を要件文から正確に読み分けられるかを問う。「鍵を自分で持ち込む」か「鍵の管理をGoogleに委ねる」かの違いが、この分野のひっかけどころになっている。", "kid": "自分の家の鍵を自分で持ち歩いて自分でかけるのがCSEK。管理人室に鍵を預けて管理人に開け閉めしてもらうのがCMEK。今回は「自分で鍵を持ち込みたい」という要件なので前者を選ぶ。", "eg": "貸金庫に、自分で持ってきた南京錠をかけるか、貸金庫会社が用意した鍵をかけてもらうかの違いに近い。同じ「鍵をかける」でも、鍵の所有者がどちらかで扱いが変わる。"}, "gcp-pca-g-q58": {"point": "IPやゾーンに縛られず動的に増減するVM間の通信を制御したいなら、ネットワークタグを条件にしたファイアウォールルールが決め手。", "why_asked": "オートスケーリングでVMが増減する環境ではIPベースの制御が破綻するという理解を問う。IAPやロードバランサとの役割の違いも同時に見られている。", "kid": "IPアドレスは会員番号のようにVMが増えるたびに変わってしまうが、ネットワークタグは「制服の色」のようなラベルなので、新しく入った人にも同じ色の制服を着せれば同じルールがそのまま適用される。", "eg": "社員証の番号は入退社のたびに変わるが、「営業部」というバッジを付けていれば、入館ゲートは番号を覚え直さなくても「営業部は2階まで」というルールをそのまま適用できる。ネットワークタグはこのバッジにあたる。"}, "gcp-pca-g-q59": {"point": "publish自体が遅いなら、バッチングの無効化が決め手。受信側の設定や保持期間をいじっても効かない。", "why_asked": "レイテンシ改善の設問では「どのレイヤーで遅れているか」を切り分ける力が問われる。送信側と受信側の設定を混同すると誤答する典型パターン。", "kid": "バスが満席になるまで発車を待つ方式だと、1人だけ乗りたい人はいつまでも出発できない。バッチングとはこの「満席待ち」のことで、無効化すれば1件でもすぐ発車（送信）できるようになる。", "eg": "宅配便が「同じ地域の荷物が集まるまで待ってからまとめて出発する」方式だと、急ぎの1個口の荷物は待たされてしまう。バッチングを切るのは、集まるのを待たず来た順にすぐ発送する方式に切り替えることに近い。"}, "gcp-pca-g-q60": {"point": "バッチとストリーミングを同じ仕組みでコスト最小に扱いたいなら、Apache Beamベースのサーバーレス基盤であるCloud Dataflowが決め手。", "why_asked": "バッチとストリーミングを別々の基盤で作ると運用が二重になるという、統合処理モデルの意義を理解しているかを問う。常時稼働クラスタとサーバーレスのコスト構造の違いも見られている。", "kid": "毎時集計（バッチ）とリアルタイム通知（ストリーミング）を別々の仕組みで作ると、2つのシステムを別々に面倒みることになる。1つのコードで両方さばける仕組みを使えば、面倒を見る対象が1つで済む。", "eg": "定食屋が「昼の大量注文をまとめて作る係」と「一品ずつ来る単品注文をその都度作る係」を別々に雇うと人件費が二重にかかる。同じ厨房・同じレシピで両方さばける体制にすれば、忙しさに応じて自動で人数が増減して無駄がない。"}, "gcp-pca-g-q61": {"point": "準拠範囲（スコープ）そのものを縮小したいなら、暗号化ではなくトークナイゼーションが決め手。復号して使う限りカード番号は保持され続けている扱いになる。", "why_asked": "「暗号化すれば安全」という思い込みと、PCI DSSの「カード番号を保持する範囲がそのまま監査対象になる」というスコープの考え方を区別できるかを問う。", "kid": "鍵をかけた金庫でも、いずれ開けて中の現金（カード番号）を使うなら、金庫は「現金を保管している場所」として警備対象であり続ける。現金の代わりに使える金券（トークン）に両替してしまえば、現金そのものはもう扱わなくて済む。", "eg": "カジノのチップに似ている。現金をチップに両替すれば、フロア中どこでもチップだけが動き、現金そのものを厳重管理しなければならない範囲はキャッシャー窓口だけに絞り込める。"}, "gcp-pca-g-q62": {"point": "平文を保持せずに重複判定もしたいなら、同じ入力が常に同じ暗号文になる決定論的暗号化が決め手。通常の暗号化では同じカードでも毎回結果が変わり重複判定ができない。", "why_asked": "「暗号化すれば重複判定もできるだろう」という誤解を突く設問。決定論的暗号化と通常の（ランダム性のある）暗号化の違いを理解しているかを問う。", "kid": "同じ人が毎回違う変装で現れたら「同一人物だ」と見分けがつかない。決定論的暗号化は、同じカード番号なら毎回必ず同じ「変装後の姿」になる方式なので、変装後の姿だけを比べれば同一カードかどうか分かる。", "eg": "指紋認証のようなもの。指紋そのもの（生の値）は見せずに、指紋から作った一定のコード（暗号文）だけを照合すれば本人確認ができる。コードが毎回変わってしまっては照合が成り立たない。"}, "gcp-pca-g-q63": {"point": "標準SQLでペタバイト級のデータを自由に集計したいなら、BigQueryが決め手。", "why_asked": "OLTP向けDB（Spanner）とドキュメントDB（Firestore）と分析用DWH（BigQuery）の得意分野の違いを、要件文の「SQLで」「大量データを」「自由に集計」から読み分けられるかを問う。", "kid": "数百万件のレシートを1件ずつ手で確認する（Firestoreのドキュメント検索やSpannerのトランザクション参照）のではなく、全部まとめて「先月の合計はいくら」と一撃で集計できる倉庫のような仕組みがBigQuery。", "eg": "図書館の閲覧カウンター（Spanner＝1冊ずつの貸し出し手続きに強い）と、蔵書全体を対象にした統計調査（BigQuery＝全体を横断して集計するのに強い）は、同じ本を扱っていても向いている作業が違う。"}, "gcp-pca-g-q64": {"point": "既存クライアントへの影響をゼロにしたまま非互換な変更を入れたいなら、APIのバージョン番号を上げて旧バージョンをそのまま残すのが決め手。", "why_asked": "API進化の設問は「後方互換をどう守るか」という運用設計の型を問う頻出テーマ。旧バージョンを残さず上書きしてしまう案は、必ず誤答の選択肢として混ざる。", "kid": "家のリフォームで間取りを大きく変えるとき、今住んでいる人を追い出さずに、新しい間取りの部屋を隣に別途用意する。住みたい人だけ引っ越せばよく、今の住人は今まで通り暮らせる。", "eg": "道路の新ルートを作るとき、旧道を通行止めにせず並行して残しておく。旧道を使い続けたいドライバーはそのまま走れて、新ルートを使いたい人だけ切り替えられる。"}, "gcp-pca-g-q65": {"point": "取りこぼしが許されないなら、送信先を直接HTTPで叩くのではなく、Pub/Sub経由で配送保証を持たせるのが決め手。", "why_asked": "「スケジュール通り実行される」ことと「確実に届く」ことは別の要件であり、後者にはメッセージングの配送保証という別の仕組みが必要になることを理解しているかを問う。", "kid": "直接電話をかけて相手が出なければ用件はそこで終わりだが、留守番電話に伝言を残しておけば、相手が後で気づいて必ず聞いてくれる。Pub/Subはこの留守番電話の役割を果たす。", "eg": "宅配便で、不在時に荷物をそのまま持ち帰ってしまう方式と、不在票を残して荷物を配送センターで預かっておき後で確実に届ける方式の違いに近い。"}, "gcp-pca-g-q66": {"point": "既存バイナリをそのまま・最小改修で動かしたいなら、コンテナ化が前提のCloud RunやCloud Functionsではなく、VMベースのMIGが決め手。", "why_asked": "「最新の基盤を使うほうが正解」という思い込みを崩す設問。移行元の資産の形（ネイティブバイナリ）を変えずに済む選択肢を選べるかを問う。", "kid": "引っ越し先で家具を全部新調しなければならないなら手間がかかるが、今ある家具をそのままトラックに積んで運べるなら、それが一番早い。VMはこの「そのまま積める」選択肢にあたる。", "eg": "手元にある紙の書類を、そのままファイルするか、いちいちデジタル化してから使うかの違いに近い。今回は「そのまま使いたい」が条件なので、変換の手間がない方を選ぶ。"}, "gcp-pca-g-q67": {"point": "静的配信はグローバルに速く、平常時は安く、決済のようなトランザクションは信頼性高くという3つを同時に満たしたいなら、CDN＋Cloud Run＋Cloud SQLの組み合わせが決め手。", "why_asked": "複数の要件（コスト・スケール・グローバル配信・トランザクション整合性）を1つの構成で同時に満たせるかを、コンポーネントごとの役割分担で組み立てさせる設問。", "kid": "お祭りの屋台で、パンフレット配りは大量に刷って各地に配れる係、注文対応は混んだときだけ人を増やせる係、お金の管理は間違いが許されない専門の会計係、というように役割を分ける発想に近い。", "eg": "コンサート当日、入場パンフレットは事前に大量印刷して各ゲートに配布し、当日窓口は混雑に応じて臨時スタッフを増減させ、チケット代の会計だけは専門の経理担当が厳密に処理する、という体制分けに似ている。"}, "gcp-pca-g-q68": {"point": "距離によるレイテンシは同一リージョン内のスケーリング強化では解消できず、近い場所にもう1つ拠点を作るのが決め手。", "why_asked": "レイテンシの原因が「処理能力不足」なのか「物理的な距離」なのかを見極める設問。原因を取り違えると的外れな対策（スケーリング強化）を選んでしまう。", "kid": "遠くの店に注文が殺到しているとき、その店のレジを増やしても配達にかかる時間の長さは縮まらない。近くにも店舗を出せば、近くの客はそちらで対応できるようになる。", "eg": "東京から大阪への荷物を、東京の配送センターの人員を増やしても届く時間は変わらない。大阪にも配送拠点を作ってこそ、大阪向けの荷物は速く届くようになる。"}, "gcp-pca-g-q69": {"point": "スケーリング中・一部ユーザーだけという症状が出ているなら、原因はインスタンスローカルな状態保持を疑うのが決め手。", "why_asked": "ステートレス設計の重要性を問う定番パターン。オートスケーリング環境ではインスタンス間でメモリが共有されないという前提を理解しているかを見る。", "kid": "受付が3人いる窓口で、1人の受付係だけが「この人は対応済み」というメモを自分の手元に書いていたら、別の受付係に回されたお客さんは対応済みだと分かってもらえない。メモは全員が見られる場所に置く必要がある。", "eg": "学校で担任の先生だけが生徒の出席簿を持っていると、代理の先生が来た授業では出席状況が分からなくなる。職員室の共有台帳に記録しておけば、誰が担当しても同じ情報を参照できる。"}, "gcp-pca-g-q70": {"point": "持ち込みライセンス（BYOL）を維持したいなら、Google提供の共有イメージや共有ホストは使わず、自前イメージをSole-Tenant Nodes上で起動するのが決め手。", "why_asked": "BYOLはライセンスコンプライアンスに直結する実務判断。「動けばよい」ではなく「どのライセンス条件で動いているか」を区別できるかを問う。", "kid": "自分が持っている会員カードを使い続けたいのに、お店が発行する新しい会員カードにサインアップしてしまったら、結局新しい契約を結んだことになってしまう。専用の個室（Sole-Tenant Nodes）で自分のカードのまま利用するのが筋になる。", "eg": "自分の車をレンタカー会社の駐車場に停めて自分の車のまま乗るか、レンタカー会社の車を借りるかの違いに近い。BYOLは前者にあたり、そのためには「自分の車専用の区画」が必要になる。"}, "gcp-pca-g-q71": {"point": "IDが既にわかっている複数件を最少のAPI呼び出しで取りたいなら、バッチgetが決め手。", "why_asked": "q56と同系統の頻出パターン。既知のKeyに対してクエリ（検索）を使う無駄を避けられるかという、コスト意識を問う設問。", "kid": "郵便受けの番号が分かっているなら、住所録を1件ずつめくって探す必要はなく、その番号の郵便受けを直接開ければよい。複数の番号を一度に開けられる仕組みならなおよい。", "eg": "コインロッカーの番号を控えておけば、ロッカーの列を端から確認して回らなくても、番号を頼りに直接そのロッカーへ行ける。複数の荷物を一度に取り出せる窓口があれば、番号を伝えるだけでまとめて出してもらえる。"}, "gcp-pca-g-q72": {"point": "他社クラウドからCloud Storageへ低コスト・短時間で移したいなら、Storage Transfer Serviceが決め手。", "why_asked": "専用のマネージド移行サービスがあることを知っているかを問う設問。自前スクリプトやETL基盤を使う遠回りな案と比較させる典型パターン。", "kid": "引っ越し業者は並行して何往復もトラックを走らせ、忘れ物がないか確認までしてくれる。自分でレンタカーを何度も往復させるより速くて安全。Storage Transfer Serviceはこの専門業者にあたる。", "eg": "大量の荷物を運ぶとき、自分で車を何往復もさせるより、引っ越し専門業者に頼めば複数台のトラックを同時に走らせて短時間で終わらせてくれる。専用サービスを使うほうが結局は速くて安い。"}, "gcp-pca-g-q73": {"point": "公開IPを持たせずに外部の一般サイトへ出て行きたいなら、Cloud NATが決め手。Private Google AccessはGoogleのサービス専用なので使えない。", "why_asked": "Private Google AccessとCloud NATの守備範囲の違い（Google向けか、一般の外部向けか）を混同していないかを問う頻出パターン。", "kid": "会社の代表電話を使えば、社員個人の携帯番号を教えずに外部へ電話をかけられる。Private Google Accessは「本社（Google）への内線」であって、外部の取引先（一般サイト）にはつながらない。", "eg": "マンションの各部屋番号を外部に教えず、管理人室の代表番号を経由して外へ電話をかける仕組みに近い。Cloud NATはこの管理人室の代表番号にあたる。"}, "gcp-pca-g-q74": {"point": "保守作業をとにかく無くしたい（NoOps）なら、クラスタ管理が残るGKEではなく、完全マネージドなCloud RunとApp Engine Standardの組み合わせが決め手。", "why_asked": "「マネージド」と「NoOps」は同じではないという区別を問う設問。GKEはマネージドサービスだがクラスタ運用は残るという、試験でよく狙われるひっかけ。", "kid": "庭付きの家（GKE）は管理会社に任せていても庭の手入れ（クラスタ管理）が自分の予定に組み込まれる。管理費込みの賃貸マンション（Cloud RunやApp Engine Standard）なら、鍵を受け取ったらあとは住むだけで手入れの心配がない。", "eg": "レンタカーは借りている間の給油や洗車を自分でする必要があるが、タクシーは乗るだけで運転や整備の心配が要らない。Cloud RunとApp Engine Standardはこのタクシーにあたる。"}, "gcp-pca-g-q75": {"point": "秒間数千件の書き込みで取りこぼしなく高スループットにしたいなら、オブジェクト名をランダム接頭辞で分散（シャーディング）させるのが決め手。", "why_asked": "Cloud Storageの内部構造（似た名前の連続書き込みがホットスポットを生む）を理解し、命名規則が性能に直結することを知っているかを問う。", "kid": "同じ受付窓口に人が殺到すると行列ができるが、受付番号をバラバラに割り振って複数の窓口に分散させれば、同時にさばける人数が増える。オブジェクト名の先頭を連番ではなくランダムにするのはこれと同じ発想。", "eg": "図書館で新着本を全部「2026年8月1日」というラベルで揃えて置くと、その棚だけ混雑する。ラベルの先頭にランダムな記号を足してあちこちの棚に分散させれば、探す人も置く人も特定の場所に集中しない。"}, "gcp-pca-g-q76": {"point": "原因不明の遅延の発生箇所を突き止めたいなら、まずリクエストの通過経路を可視化するCloud Traceが決め手。", "why_asked": "原因不明のトラブルに対して、対症療法（再起動やキャッシュ延長）ではなく、まず可視化して原因を特定するという調査の正しい順序を問う。", "kid": "どこで渋滞しているか分からないまま闇雲に道を広げるのではなく、まず車の通過時刻を区間ごとに記録して、どこで詰まっているかを地図に描き出す。Cloud Traceはこの記録係にあたる。", "eg": "体調不良の原因が分からないのに、とりあえず栄養ドリンクを飲むのではなく、まず健康診断で体のどこに異常があるか調べるのが先。原因を見える化してから手を打つ、という順序が大事。"}, "gcp-pca-g-q77": {"point": "端末を問わず常に最新のCLI環境を統一したいなら、Cloud Shellが決め手。配布・同期方式は更新のたびに手間が残る。", "why_asked": "「環境を配って回る」発想と「ブラウザ経由で共有の環境そのものを使う」発想の違いを問う。運用の手間が最小な選択肢を見抜けるかがポイントになる。", "kid": "全員に同じ工具箱を配って回ると、新しい工具が出るたびに配り直しが必要になる。全員が同じ作業場に集まって作業すれば、作業場側の工具を更新するだけで全員が最新を使える。Cloud Shellはこの共有の作業場にあたる。", "eg": "各家庭に同じ辞書を配って回るのではなく、みんなが同じ図書館の最新版の辞書を使いに来るようにすれば、改訂のたびに配り直す手間がなくなる。"}, "gcp-pca-g-q78": {"point": "即座にフェイルオーバーしたいなら、障害発生の時点でデータが既にもう一方のゾーンにも存在している構成、つまりリージョナルSSD永続ディスクが決め手。", "why_asked": "「即座に」という言葉が、データのコピーが事後（スナップショット）か常時同期（リージョナルディスク）かを見分けるカギになることを問う。", "kid": "片方の家が火事になってから慌てて荷物を運び出す（スナップショットからの復元）のでは間に合わない。最初から同じ荷物をもう一軒の家にも常に置いてある構成なら、すぐそちらで生活を再開できる。", "eg": "双子の家に全く同じ家具を常に置いておけば、片方が停電してもすぐもう片方に移り住める。定期的に写真を撮って後で家具を揃え直す方式では、揃え直すまでの間の家具が失われてしまう。"}, "gcp-pca-g-q79": {"point": "アクセス数の変動が激しく手動対応を避けたいなら、App Engine Standard（自動スケール）とFirestore（サーバーレスDB）の組み合わせが決め手。", "why_asked": "変動幅が大きいワークロードに対して、人が容量計画を都度調整する構成（単一VMやMIG）を選ばせないための設問。「完全マネージド」というキーワードを見落とさないかを問う。", "kid": "お客さんが来る日と来ない日の差が激しいお店で、毎回店員の人数を店長が電話で手配するのではなく、来客数に応じて自動でレジが増減する仕組みにしておけば、店長は何もしなくてよい。", "eg": "花火大会の日だけ客が殺到する屋台で、毎回アルバイトを電話で呼び集めるのではなく、混雑センサーで自動的に助っ人が現れるようにしておけば、店主は当日何も手配しなくてよい。"}, "gcp-pca-g-q80": {"point": "同じデータで権限だけ分けたいなら、PIIを除いたビューを別データセットに置いて承認付きビューでアクセスを分離するのが決め手。", "why_asked": "データを複製せずに権限だけを分離する設計と、複製してしまう設計のコスト・保守性の違いを問う。BigQueryでのデータガバナンスの定石を問う設問。", "kid": "同じ金庫の中身を、机の配置だけで分けようとすると、誰かが設定を間違えて金庫を開けてしまう危険が残る。中身を複製せず、閲覧専用の窓（ビュー）だけを別の部屋（別データセット）に用意すれば、元の金庫には別室から直接触れない。", "eg": "図書館の貴重書庫は司書だけが入れるが、一般利用者にはコピーを別の閲覧室に置いておく。原本を持ち出させず、複製もその都度作らず、閲覧室の入退室権限だけで管理する。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pca-g')
  AND q.explanation_data IS NOT NULL;

COMMIT;
